-- ════════════════════════════════════════════════════════════════════
-- Flashcard cloze QUALITY fixes — 2026-07-15 (bank-wide answer-leak + ASCII-formula sweep)
-- Captures live UPDATE-by-id edits so they are reproducible in git (NOT applied via reseed —
-- reseeding a deck wipes SRS progress; these UPDATEs preserve flashcard ids and user state).
-- Two defect classes fixed: (1) cloze ANSWER-LEAK — the masked answer recoverable from visible
--   text; fixed by wrapping the recurring term into the SAME {{cN::}} group (or minimal reword).
--   (2) ASCII chemical formulas -> Unicode sub/superscripts (flashcards render plain text).
-- Plus one cloze_count integrity fix (a 3-group card stored as 2 -> its 3rd blank was unschedulable).
-- IDEMPOTENT: UPDATE-by-id with the exact current production values; safe to re-run.
-- ════════════════════════════════════════════════════════════════════

BEGIN;

-- ── Acids and Bases ──
UPDATE flashcards SET cloze_text = 'Two classic MCAT buffers: acetic acid + sodium acetate (an {{c1::acid buffer}}, pKa ≈ 4.76); ammonia + ammonium chloride (a {{c1::basic buffer}}).', cloze_count = 1 WHERE id = '12a05f4c-8ca2-4b4a-91df-bb0872013ab6';
UPDATE flashcards SET cloze_text = 'Every Arrhenius acid is also a {{c1::Brønsted-Lowry}} acid, and every {{c1::Brønsted-Lowry}} acid is also a {{c1::Lewis}} acid — but the converse is NOT necessarily true.', cloze_count = 1 WHERE id = '13308669-e5d7-4636-bcac-9ac98a043d09';
UPDATE flashcards SET cloze_text = 'A buffer works because its {{c1::weak acid}} component neutralizes added {{c2::OH⁻}} (becoming the {{c1::conjugate base}}), while its {{c1::conjugate base}} neutralizes added {{c2::H⁺}} (becoming the {{c1::weak acid}}).', cloze_count = 2 WHERE id = '15dab5b6-331c-4609-a915-6f3022ccad34';
UPDATE flashcards SET cloze_text = 'The MCAT strong bases are {{c1::NaOH, KOH}}, and other soluble hydroxides of {{c2::Group IA}} ({{c2::alkali metal}}) metals; Group IIA hydroxides like Ca(OH)₂ are also strong if soluble.', cloze_count = 2 WHERE id = '8a78588e-9485-406b-98b8-d2c81771093b';
UPDATE flashcards SET cloze_text = '{{c1::Gram equivalent weight}} is the mass of a compound that produces one {{c1::equivalent}} (one mole of H⁺ or OH⁻).', cloze_count = 1 WHERE id = '983b4c5a-b1df-46d4-bed0-ef722a7960da';
UPDATE flashcards SET cloze_text = 'A {{c1::salt}} is an ionic compound formed from the cation of a base and the anion of an acid; in solution, {{c1::salt}}s dissociate into their constituent ions.', cloze_count = 1 WHERE id = 'be9f1bda-15e9-4e0a-98cc-c680428a3d6b';
UPDATE flashcards SET cloze_text = 'The conjugate of a {{c1::weak}} acid is itself a {{c1::weak}} base, and the conjugate of a {{c1::weak}} base is a {{c1::weak}} acid — both retain noticeable reactivity.', cloze_count = 1 WHERE id = 'e4e5eb1b-0e7a-4d0c-bca3-c05741f6130a';
-- ── Alcohols ──
UPDATE flashcards SET cloze_text = 'A {{c1::phenol}} is a benzene ring with a {{c2::hydroxyl group}} directly attached; {{c1::phenols}} are {{c3::more acidic}} than ordinary alcohols.', cloze_count = 3 WHERE id = 'cc1663f1-4dee-4e08-ac89-e6d25ebbd1a5';
-- ── Aldehydes and Ketones I ──
UPDATE flashcards SET cloze_text = 'For molecules of the same chain length, boiling points rank {{c1::alcohol > carbonyl > alkane}} — {{c1::alcohols}} can {{c2::hydrogen bond}}, {{c1::carbonyls}} have {{c3::dipole–dipole interactions only}}, and {{c1::alkanes}} have only van der Waals forces.', cloze_count = 3 WHERE id = '0310c7b1-1936-41d3-b855-2d292e2a6ea5';
UPDATE flashcards SET cloze_text = '{{c1::LiAlH₄}} is a strong reducing agent that handles carboxylic acids, esters, amides, plus {{c3::aldehydes and ketones}}; {{c2::NaBH₄}} is milder — useful when you want to reduce only {{c3::aldehydes or ketones}} and leave other functional groups intact.', cloze_count = 3 WHERE id = '05a4ca1a-5ad6-412f-ad0d-fd86f308bf62';
UPDATE flashcards SET cloze_text = '{{c1::Primary alcohols}} oxidize to {{c2::aldehydes}} only when using {{c3::PCC}} (stronger oxidizers overoxidize to carboxylic acids); {{c1::secondary alcohols}} oxidize to {{c2::ketones}} with {{c3::PCC}}, Na₂Cr₂O₇, CrO₃, or KMnO₄.', cloze_count = 3 WHERE id = '3eecdc0c-2bfc-49aa-ae78-87273fad54f4';
UPDATE flashcards SET cloze_text = 'Ketones {{c1::cannot be further oxidized}} (the carbonyl carbon is already {{c1::maximally oxidized}} without breaking a C–C bond), but they can be reduced back to {{c2::secondary alcohols}}.', cloze_count = 2 WHERE id = 'a1563b03-c323-4be3-af59-8e5ac4a53568';
UPDATE flashcards SET cloze_text = 'A {{c1::ketone}} contains an {{c2::internal carbonyl}} bonded to {{c3::two alkyl groups}} — the {{c2::carbonyl}} is never at the end of a chain.', cloze_count = 3 WHERE id = 'aacadc33-a458-4636-873b-46b81620dcfc';
UPDATE flashcards SET cloze_text = 'In the first step, the {{c1::nucleophile attacks the carbonyl carbon}}, pushing the {{c2::π electrons up onto the oxygen}} to form an alkoxide intermediate.', cloze_count = 2 WHERE id = 'c5fd0e99-38da-4c0d-9344-af4fc4e06afc';
-- ── Aldehydes and Ketones II: Enolates ──
UPDATE flashcards SET cloze_text = 'The {{c1::enolate}} conjugate base is stabilized by resonance — the negative charge can sit on the {{c2::α-carbon (carbanion form)}} or, more stably, on the {{c3::carbonyl oxygen}} ({{c1::enolate}} form).', cloze_count = 3 WHERE id = '86972e49-27cb-442d-88a3-4eadf621b998';
UPDATE flashcards SET cloze_text = 'The {{c1::α-carbon}} is the {{c1::carbon}} directly {{c2::adjacent to the carbonyl carbon}}, and any {{c3::hydrogens}} attached to it are called {{c3::α-hydrogens}}.', cloze_count = 3 WHERE id = '8ed3ee2d-dbe7-449b-a7e8-3dfaedf8cefe';
UPDATE flashcards SET cloze_text = '{{c1::Enamines}} form when a {{c2::secondary amine}} reacts with an aldehyde or ketone — they are the nitrogen analogs of enols and are {{c3::tautomers of imines}} (primary amines instead give {{c3::imines}}).', cloze_count = 3 WHERE id = 'acb69ae8-7f1e-490e-9359-6ea078916137';
UPDATE flashcards SET cloze_text = 'The {{c1::keto form}} (C=O) is much more stable than the {{c2::enol form}} (C=C–OH, a vinyl alcohol); the equilibrium lies {{c3::far to that side}}.', cloze_count = 3 WHERE id = 'e293d402-5d81-4506-8e29-cb365a1e3f79';
-- ── Amino Acids ──
UPDATE flashcards SET cloze_text = '{{c1::Methionine}} (Met, M) is the universal {{c2::translation start codon AUG}} amino acid — every nascent eukaryotic polypeptide begins with {{c1::methionine}} on its {{c3::N-terminus}} (sometimes cleaved post-translationally).', cloze_count = 3 WHERE id = '521cc80a-5d89-4cee-8fee-731a5b9b98e8';
UPDATE flashcards SET cloze_text = '{{c1::Nonpolar (hydrophobic)}} amino acid side chains tend to be buried in the {{c2::interior}} of a folded protein, away from water — the {{c1::hydrophobic}} effect is the dominant thermodynamic force driving protein folding.', cloze_count = 2 WHERE id = '626e95d2-5126-45c0-ab69-7de2e98b0e75';
UPDATE flashcards SET cloze_text = 'Side-chain pKa values of the basic amino acids: {{c1::lysine ≈ 10.5}}, {{c2::arginine ≈ 12.5}}, and {{c3::histidine ≈ 6.0}}. {{c1::Lysine}} and {{c2::arginine}} are essentially always protonated at physiological pH; {{c3::histidine}} straddles 7.4 and can be either form.', cloze_count = 3 WHERE id = '8dba063f-312a-4123-9c13-5c842ffed692';
UPDATE flashcards SET cloze_text = 'Seven amino acids have ionizable side chains: the three {{c1::basic}} ({{c2::Lys, Arg, His}}), the two {{c3::acidic}} ({{c4::Asp, Glu}}), and two with weakly {{c3::acidic}} groups that ionize only at higher pH ({{c5::Tyr, Cys}}).', cloze_count = 5 WHERE id = '9470bc20-6bcb-4016-81a8-d18af8f56df5';
UPDATE flashcards SET cloze_text = 'The two sulfur-containing amino acids are {{c1::methionine}} and {{c1::cysteine}}. The former contains a {{c2::thioether (-S-CH₃)}}, while the latter contains a reactive {{c2::thiol (-SH)}} — only the latter is reactive enough to form disulfide bonds.', cloze_count = 2 WHERE id = 'a9aa13c4-1a50-42f6-b007-b358174b1e21';
UPDATE flashcards SET cloze_text = 'Standard backbone pKa values shared by all {{c2::amino}} acids: the {{c1::α-carboxyl group ≈ 2.0}} and the {{c2::α-amino group ≈ 9–10}}. At physiological pH both are ionized, producing the zwitterionic form.', cloze_count = 2 WHERE id = 'd62f0aed-b2b7-4150-95fe-75d12c25580c';
-- ── Amino Acids, Peptides, and Proteins ──
UPDATE flashcards SET cloze_text = '{{c1::Quaternary structure}} is the spatial arrangement of two or more polypeptide {{c2::subunits}} into a single functional complex; not every protein has {{c1::quaternary structure}}.', cloze_count = 2 WHERE id = '497fb7d1-8cc8-4f90-acef-866076feeb47';
UPDATE flashcards SET cloze_text = '{{c1::Asparagine}} and {{c1::glutamine}} carry an {{c2::amide}} group on their side chain; this {{c2::amide}} nitrogen does not gain or lose protons with pH.', cloze_count = 2 WHERE id = '8b3c9a01-3804-44c0-a415-e51c9ea5aa53';
UPDATE flashcards SET cloze_text = '{{c1::Tryptophan}} has an indole double-ring system containing a nitrogen; {{c2::phenylalanine}} has a plain benzyl ring; {{c3::tyrosine}} is {{c2::phenylalanine}} with an added hydroxyl group.', cloze_count = 3 WHERE id = 'a7222539-3a83-4937-9280-a92d4b14a2ea';
UPDATE flashcards SET cloze_text = 'Human proteins are built from {{c1::20}} {{c2::α-amino acids}} encoded by the standard genetic code; these are the proteinogenic (proteogenic) {{c2::amino acids}}.', cloze_count = 2 WHERE id = 'b3e4455f-5a53-4609-a418-e501ea136965';
-- ── Analyzing Organic Reactions ──
UPDATE flashcards SET cloze_text = 'Because SN1''s rate-limiting step involves only the {{c1::substrate}}, the rate depends only on {{c1::[substrate]}} — making SN1 a {{c2::first-order}} reaction overall.', cloze_count = 2 WHERE id = '04f35908-3ac4-4ffc-aa13-c3a2db722fb8';
UPDATE flashcards SET cloze_text = '{{c1::SN1}} (unimolecular nucleophilic substitution) is a {{c2::two-step}} reaction: Step 1 ({{c3::rate-limiting}}) — leaving group departs to form a {{c4::carbocation}}; Step 2 — nucleophile attacks the {{c4::carbocation}}.', cloze_count = 4 WHERE id = '13dd27d1-8095-43ad-8aac-0031f7e81439';
UPDATE flashcards SET cloze_text = 'SN2''s single step involves both {{c1::substrate}} and {{c1::nucleophile}}, so the rate depends on {{c1::[substrate] × [nucleophile]}} — making SN2 a {{c2::second-order}} reaction overall.', cloze_count = 2 WHERE id = '2ec209b0-9e6b-4ac1-838c-9ee2ee14ae34';
UPDATE flashcards SET cloze_text = '{{c1::Oxidation state}} is the hypothetical charge an atom would carry if all bonds were {{c2::fully ionic}}; remember {{c3::OIL RIG}} — {{c1::Oxidation}} Is Loss of electrons, Reduction Is Gain.', cloze_count = 3 WHERE id = '371c35f1-b554-4eea-b80e-f43cb35085fb';
UPDATE flashcards SET cloze_text = 'A {{c1::nucleophile}} ("nucleus-loving") carries {{c2::lone pairs or π bonds}} that form new bonds to electrophiles; {{c1::nucleophiles}} are often {{c3::negatively charged}} or carry partial negative charge.', cloze_count = 3 WHERE id = '6a3ff37a-0387-4d9d-954e-aec90b82d1ea';
UPDATE flashcards SET cloze_text = 'An {{c1::electrophile}} ("electron-loving") is {{c2::positively charged or positively polarized}} and accepts an electron pair when forming a bond; {{c1::electrophiles}} essentially always act as {{c3::Lewis acids}}.', cloze_count = 3 WHERE id = '7b60a211-0dac-4d01-9eb1-a4ca35dbe010';
UPDATE flashcards SET cloze_text = 'SN2 prefers {{c1::less substituted}} carbons ({{c2::methyl > 1° > 2°}}; 3° essentially won''t react) because the backside is blocked by {{c3::steric hindrance}} on {{c1::substituted}} substrates.', cloze_count = 3 WHERE id = 'a94a8403-5573-4eb8-aec4-2a3ccbf6d410';
-- ── Atomic and Nuclear Phenomena ──
UPDATE flashcards SET cloze_text = 'Whether emission happens depends on photon {{c1::frequency}}, not on {{c2::intensity}} — below the threshold {{c1::frequency}}, even a {{c3::very bright (high-intensity)}} beam ejects nothing.', cloze_count = 3 WHERE id = '43de4f2a-714d-4d72-8ad5-6498adf28c25';
UPDATE flashcards SET cloze_text = 'The atomic number Z counts {{c1::protons}}, the mass number A counts {{c1::protons}} + {{c2::neutrons}}, so the number of the latter is {{c3::A − Z}}.', cloze_count = 3 WHERE id = '91f9fb12-d969-46ad-b90f-b666deb94b28';
-- ── Bioenergetics and Regulation of Metabolism ──
UPDATE flashcards SET cloze_text = '{{c1::ATP (adenosine triphosphate)}} consists of an {{c1::adenosine}} (adenine + ribose) attached to {{c2::three}} phosphate groups in series.', cloze_count = 2 WHERE id = '237c951d-3f81-43a0-b958-8b9fe317df29';
UPDATE flashcards SET cloze_text = 'Many cellular redox reactions are mediated by reusable {{c1::electron carriers}} that shuttle high-energy {{c1::electrons}} between enzymes; {{c1::carriers}} may be {{c2::soluble}} or {{c2::membrane-bound}}.', cloze_count = 2 WHERE id = '3b30d5bb-c562-4f10-b532-0ab2b30e4a04';
UPDATE flashcards SET cloze_text = 'When H⁺ is a {{c1::reactant}}, lowering pH (more H⁺) drives the reaction {{c2::forward}}; when H⁺ is a {{c1::product}}, lowering pH shifts equilibrium {{c2::backward}} (basic conditions favor the reverse).', cloze_count = 2 WHERE id = '475d5149-93da-46a0-b9b3-d51985e5bf7b';
UPDATE flashcards SET cloze_text = '{{c1::Entropy (ΔS)}} measures the degree of {{c2::disorder}} or energy dispersion in a system; increasing {{c1::entropy}} favors spontaneous reactions.', cloze_count = 2 WHERE id = '4f813c8e-8bbb-42bb-bc5a-d85dfadea52d';
UPDATE flashcards SET cloze_text = 'ATP is a poor {{c1::long-term storage}} molecule because it is unstable and cycles rapidly; fats and glycogen are used for {{c1::long-term storage}} instead.', cloze_count = 1 WHERE id = '557d516c-f80b-44e5-a3f5-45121e513b2c';
UPDATE flashcards SET cloze_text = 'In the liver and muscle, insulin activates {{c1::glucokinase}} and {{c2::glycogen synthase}} while inactivating {{c3::glycogen}} phosphorylase — net effect: glucose storage as {{c3::glycogen}}.', cloze_count = 3 WHERE id = '55cfe696-6b8c-4451-94a8-d9291093dbd9';
UPDATE flashcards SET cloze_text = 'The liver is the body''s primary regulator of {{c1::blood glucose}}, storing it as glycogen after meals and releasing it through glycogenolysis and gluconeogenesis during fasting.', cloze_count = 1 WHERE id = '6f7e0298-fa1e-4f77-afd5-409357578562';
UPDATE flashcards SET cloze_text = '{{c1::Enthalpy (ΔH)}} measures the total heat content change during a reaction; at constant pressure, {{c1::ΔH}} equals the heat exchanged with the surroundings.', cloze_count = 1 WHERE id = '7df47716-8fa6-4aae-a95b-a892d3e265ba';
UPDATE flashcards SET cloze_text = 'The most important physiological controller of insulin secretion is {{c1::plasma glucose}}; insulin release is directly proportional to {{c1::blood glucose}} concentration.', cloze_count = 1 WHERE id = '9308fd1c-fa49-4c8a-85d7-bc5f36a4bdd7';
UPDATE flashcards SET cloze_text = 'The brain consumes about {{c1::25%}} of the body''s daily {{c2::glucose}}; under normal conditions it relies entirely on {{c2::glucose}} from the bloodstream because fatty acids cannot cross the blood-brain barrier.', cloze_count = 2 WHERE id = 'b390eaa9-cfc1-4a52-b8bb-173c2cd6d814';
UPDATE flashcards SET cloze_text = 'A reaction is always spontaneous when ΔH is {{c1::negative}} and ΔS is {{c1::positive}}; always nonspontaneous when ΔH is {{c1::positive}} and ΔS is {{c1::negative}}.', cloze_count = 1 WHERE id = 'f04e3302-2a15-40f9-a1da-e35cf43e9cfb';
-- ── Bonding ──
UPDATE flashcards SET cloze_text = 'A {{c1::sigma (σ) bond}} forms by {{c2::head-to-head}} overlap of orbitals along the internuclear axis; every {{c3::single bond}} is a {{c1::sigma bond}}.', cloze_count = 3 WHERE id = 'ac092d22-0677-46e9-b668-73d58cd033d2';
UPDATE flashcards SET cloze_text = 'In a conjugated system, the aligned {{c2::p orbitals}} overlap continuously, allowing pi electrons to {{c1::delocalize}} through the {{c2::shared p orbital backbone}}.', cloze_count = 2 WHERE id = 'ec1a2288-afb4-4710-b688-7b63f7ad947c';
UPDATE flashcards SET cloze_text = 'As the number of bonds between two atoms grows, bond length {{c1::decreases}} and bond strength {{c2::increases}} — triple < double < single in length, and triple > double > single in strength.', cloze_count = 2 WHERE id = 'f452fb0b-fffc-4f17-a8c4-d2b874825811';
-- ── Bonding & Chemical Interactions ──
UPDATE flashcards SET cloze_text = 'When polar bond vectors do {{c1::not}} cancel because of asymmetric geometry, the molecule has a net {{c2::dipole moment}} and is overall polar (e.g., H₂O).', cloze_count = 2 WHERE id = '1951fb4d-c409-4d64-a086-00ce09015d02';
UPDATE flashcards SET cloze_text = 'A {{c1::nonpolar covalent}} bond shares electrons {{c2::equally}} between the two atoms; bonds between identical atoms (e.g., H–H, O=O) are always {{c1::nonpolar covalent}}.', cloze_count = 2 WHERE id = '1bf7da01-0a02-45ba-a4f5-79f3530edfdd';
UPDATE flashcards SET cloze_text = 'To draw a Lewis structure: sum {{c1::valence electrons}} from all atoms (adjust for charge); place single bonds to the {{c2::central atom}}; complete octets on the outer atoms; place leftover electrons on the {{c2::central atom}}.', cloze_count = 2 WHERE id = '1e61a2a8-4a38-46e9-b90f-0231c8b7ed95';
UPDATE flashcards SET cloze_text = 'A {{c1::sigma (σ)}} bond is formed by the {{c2::head-on}} overlap of two atomic orbitals along the internuclear axis; every single bond is a {{c1::sigma}} bond.', cloze_count = 2 WHERE id = '38876881-a321-416b-a3da-3081356c9e91';
UPDATE flashcards SET cloze_text = 'If two proposed Lewis structures differ in {{c1::bond connectivity}} or atom arrangement, they are different {{c2::compounds}}, not resonance structures of the same {{c2::compound}}.', cloze_count = 2 WHERE id = '4a05e396-280f-4809-8e1a-7b81426a86a2';
UPDATE flashcards SET cloze_text = '{{c1::VSEPR (Valence Shell Electron Pair Repulsion)}} theory predicts molecular geometry by arranging {{c1::electron-pair}} regions around the central atom as {{c2::far apart}} as possible to minimize {{c1::repulsion}}.', cloze_count = 2 WHERE id = '4e2a5ccd-4d71-41bc-8ed6-4c1ebd28a30d';
UPDATE flashcards SET cloze_text = 'As bond order {{c1::increases}}, bond energy {{c1::increases}}; breaking a triple bond requires more energy than a double, which requires more than a single.', cloze_count = 1 WHERE id = '7595fd76-3fa0-438e-97af-edef47c03123';
UPDATE flashcards SET cloze_text = '{{c1::4}} regions of electron density give a {{c2::tetrahedral}} geometry with {{c3::109.5°}} bond angles (e.g., CH₄, NH₄⁺).', cloze_count = 3 WHERE id = '8feda8ad-ea39-4aa0-b02d-21e05d013044';
UPDATE flashcards SET cloze_text = 'The sum of the formal {{c1::charges}} of all atoms in a molecule or ion equals the overall {{c1::charge}} of that molecule or ion.', cloze_count = 1 WHERE id = 'a6ca9757-b53c-42d8-b5c2-1e88943f2c96';
UPDATE flashcards SET cloze_text = 'A molecule with only {{c1::nonpolar}} bonds is always {{c1::nonpolar}} overall — there are no bond dipoles to cancel or reinforce.', cloze_count = 1 WHERE id = 'ca285f13-17e2-45c7-9f1c-863e979c14df';
-- ── Brain, Behavior & Development ──
UPDATE flashcards SET cloze_text = 'Imbalances of norepinephrine are linked to mood and {{c4::anxiety}} disorders: {{c1::low}} norepinephrine levels are associated with {{c2::depression}}, while {{c3::high}} levels are associated with {{c4::anxiety and mania}}.', cloze_count = 4 WHERE id = '03462709-b7db-421d-8f04-81a471de5690';
UPDATE flashcards SET cloze_text = 'The peripheral nervous system contains {{c1::31}} pairs of {{c2::spinal}} nerves (emanating from the {{c2::spinal}} cord) and {{c1::12}} pairs of {{c3::cranial}} nerves (emanating directly from the brain).', cloze_count = 3 WHERE id = '08b24ba3-4262-45cd-8143-fc39b397ef6a';
UPDATE flashcards SET cloze_text = 'The {{c1::pituitary gland}} is sometimes called the {{c2::master gland}} because it secretes hormones that regulate other endocrine glands throughout the body. The {{c3::anterior pituitary}} actually performs this regulatory role; the posterior {{c1::pituitary}} instead stores and releases hormones made in the hypothalamus.', cloze_count = 3 WHERE id = '16c551d9-9fa6-4fbd-9965-28101bfdf9e3';
UPDATE flashcards SET cloze_text = '{{c1::Endorphins}} are the most important {{c2::peptide neurotransmitters}} (also called neuropeptides). They act as natural painkillers with effects similar to morphine and other opioid drugs. {{c2::Peptide}} NTs are typically {{c3::slow-acting but longer-lasting}} than small-molecule {{c2::neurotransmitters}}.', cloze_count = 3 WHERE id = '207ae104-9b4e-4fe1-8867-616baec99738';
UPDATE flashcards SET cloze_text = '{{c1::Dopamine}} maintains {{c2::smooth movement and steady posture}} via the basal ganglia. Loss of {{c1::dopaminergic}} neurons in the basal ganglia produces {{c3::Parkinson''s disease}}; excess {{c1::dopamine}} activity (or oversensitivity to it) is implicated in the positive symptoms of {{c4::schizophrenia}} — the {{c1::dopamine}} hypothesis.', cloze_count = 4 WHERE id = '2f310826-4c58-45b3-ac5f-abe99e75ca07';
UPDATE flashcards SET cloze_text = 'A {{c1::teratogen}} is any substance or exposure during pregnancy that disrupts normal fetal development. Major {{c1::teratogen}}s include {{c2::alcohol, nicotine, x-rays, and certain viruses}} that cross the placenta. {{c3::Maternal malnutrition}} is considered the single leading cause of abnormal prenatal development.', cloze_count = 3 WHERE id = '41585124-fdb6-49df-9e63-ed4441f5975c';
UPDATE flashcards SET cloze_text = 'A {{c1::critical period}} is a developmental window during which the nervous system is especially {{c2::susceptible to environmental input}}. Skills or traits not acquired during the {{c1::critical period}} may be difficult or impossible to acquire later — language acquisition is the canonical example.', cloze_count = 2 WHERE id = '42fd933d-7825-4b03-bbc1-63cc41089aba';
UPDATE flashcards SET cloze_text = '{{c1::Lesion studies}} infer the function of a brain region by observing what behavioral capacity is lost when that region is damaged. In humans, naturally occurring {{c1::lesions}} (from stroke, tumor, or injury) are observed; in animals, {{c1::lesions}} can be created experimentally — most precisely using {{c2::stereotactic instruments}} that target specific regions in three-dimensional coordinates.', cloze_count = 2 WHERE id = '454ea1cc-1cb3-4aee-8050-1ce994536dae';
UPDATE flashcards SET cloze_text = 'Behavioral geneticists use three complementary study designs. {{c1::Family studies}} compare relatives but cannot separate shared genes from shared environment. {{c2::Twin studies}} compare concordance rates between {{c3::monozygotic (MZ) and dizygotic (DZ)}} {{c2::twins}} to isolate genetic effects. {{c4::Adoption studies}} compare children to both biological and adoptive parents to disentangle genetics from upbringing.', cloze_count = 4 WHERE id = '6dbdce34-a2ae-4274-b802-937c7a32b092';
UPDATE flashcards SET cloze_text = 'The {{c1::basal ganglia}} are forebrain nuclei that coordinate {{c2::smooth, intentional movement}} and maintain {{c3::postural stability}}. They form part of the {{c4::extrapyramidal motor system}}, influencing motor output without directly driving motor neurons.', cloze_count = 4 WHERE id = '701666a9-d2ea-4614-8b58-35d75fbbad92';
UPDATE flashcards SET cloze_text = 'The nervous system divides into two anatomical components. The {{c1::central nervous system (CNS)}} consists of the {{c2::brain and spinal cord}}; the {{c3::peripheral nervous system (PNS)}} consists of all nerve tissue outside the {{c1::CNS}}.', cloze_count = 3 WHERE id = '7e3e2ade-598b-484d-9180-c234ee9746ba';
UPDATE flashcards SET cloze_text = 'The endocrine system is the body''s second major communication network, using chemical messengers called {{c1::hormones}}. It is {{c2::slower}} than the nervous system because {{c1::hormones}} travel to their targets through the {{c3::bloodstream}}, but its effects are typically longer-lasting.', cloze_count = 3 WHERE id = '818f436b-9dea-42f3-b3f7-09e220aff7a2';
UPDATE flashcards SET cloze_text = 'Cortical regions are classified as either {{c1::projection}} or {{c2::association}} areas. {{c1::Projection}} areas perform rudimentary motor or sensory tasks — the primary motor cortex and the primary somatosensory cortex are classic examples. {{c2::Association}} areas integrate input from diverse regions to enable higher-order processing such as planning and decision-making. The systematic body-part organization of the motor cortex is visualized in the {{c3::motor homunculus}}.', cloze_count = 3 WHERE id = 'a773b598-4a42-45ab-896c-20de8519f664';
UPDATE flashcards SET cloze_text = '{{c1::Parkinson''s disease}} is caused by the loss of {{c2::dopaminergic neurons in the basal ganglia}}, leading to characteristic symptoms: resting tremors, jerky movements, and posture instability. Imbalances of {{c2::basal ganglia}} activity also play a role in {{c3::schizophrenia and obsessive-compulsive disorder}}.', cloze_count = 3 WHERE id = 'a7f91b57-7662-4041-98a2-befafd2b4860';
UPDATE flashcards SET cloze_text = 'A trait or behavior''s {{c1::adaptive value}} is the extent to which it benefits a species'' {{c2::evolutionary fitness}} — i.e., its contribution to survival and reproduction. Traits with high {{c1::adaptive value}} tend to be preserved by {{c3::natural selection}}.', cloze_count = 3 WHERE id = 'ac962adb-d19e-4e47-a92a-0f8b5f230cba';
UPDATE flashcards SET cloze_text = 'The {{c1::amygdala}} plays a key role in {{c2::defense and aggression}}, processing the emotions of {{c3::fear and rage}}. Damage to the {{c1::amygdala}} produces docility and hypersexual states — the classic Klüver-Bucy pattern.', cloze_count = 3 WHERE id = 'b2a098d4-8d00-4454-9e2d-b327088fa830';
UPDATE flashcards SET cloze_text = '{{c1::Serotonin}} is a biogenic amine neurotransmitter that modulates {{c2::mood, sleep, eating, and dreaming}}. Low {{c1::serotonin}} is associated with {{c3::depression}}; abnormally high {{c1::serotonin}} activity is associated with {{c4::manic states}}.', cloze_count = 4 WHERE id = 'b522cf64-01ce-4178-8351-8f89fe7de810';
UPDATE flashcards SET cloze_text = 'The {{c1::cerebellum}} sits at the back of the hindbrain and is responsible for {{c2::posture, balance, and coordinated motor movement}}. Damage to the {{c1::cerebellum}} produces characteristic deficits: clumsiness, loss of balance, and slurred speech.', cloze_count = 2 WHERE id = 'b8c348c2-9d1e-4aef-aacc-585b7b8dcfe2';
UPDATE flashcards SET cloze_text = 'The {{c1::nature vs. nurture}} debate asks how much of behavior is determined by {{c2::inherited characteristics}} and how much by {{c3::environment and experience}}. The modern consensus is that virtually every behavioral trait reflects an interaction between the two.', cloze_count = 3 WHERE id = 'e8210b4c-be3c-4236-b04a-7bd10833e5f4';
UPDATE flashcards SET cloze_text = 'The midbrain contains two prominent paired nuclei called the {{c1::colliculi}}. The {{c2::superior}} colliculus receives {{c3::visual}} sensory input and mediates {{c3::visual}} reflexes; the {{c2::inferior}} colliculus receives {{c3::auditory}} sensory input and mediates reflexes such as turning toward a sudden loud noise.', cloze_count = 3 WHERE id = 'ec589c8c-7dc3-4e0b-87cb-b204302939ff';
UPDATE flashcards SET cloze_text = 'The {{c1::occipital lobe}} sits at the rear of the brain and contains the {{c2::visual cortex (striate cortex)}}, which performs the bulk of {{c2::visual}} processing.', cloze_count = 2 WHERE id = 'efdebacc-a337-4ceb-98dc-a5a312a161c4';
UPDATE flashcards SET cloze_text = 'Most cortical communication with the body is {{c1::contralateral}}: the left hemisphere controls and receives from the right side of the body, and vice versa. Some functions communicate {{c2::ipsilaterally}} (same side), but the {{c1::contralateral}} pattern dominates.', cloze_count = 2 WHERE id = 'f0b17715-c545-4df8-9859-2a3a2941f87c';
-- ── Carbohydrate Metabolism II ──
UPDATE flashcards SET cloze_text = 'Citric acid cycle — Step 8: {{c1::malate dehydrogenase}} oxidizes malate to {{c2::oxaloacetate}}, producing the third {{c3::NADH}}; the regenerated {{c2::oxaloacetate}} is ready to start another cycle.', cloze_count = 3 WHERE id = '124a272f-6245-4b78-a2a5-feadf6a2875d';
UPDATE flashcards SET cloze_text = 'Because Complex II does not pump protons, electrons that enter via {{c1::FADH₂}} skip Complex I and contribute fewer protons to the gradient — yielding ~{{c2::1.5 ATP}} per {{c1::FADH₂}} vs ~2.5 ATP per NADH.', cloze_count = 2 WHERE id = '18991078-fecc-4022-b90a-5ccbab635a36';
UPDATE flashcards SET cloze_text = 'Citric acid cycle — Step 3: {{c1::isocitrate dehydrogenase}} (the rate-limiting enzyme of the TCA cycle) oxidatively decarboxylates {{c1::isocitrate}} to {{c2::α-ketoglutarate}}, releasing the first {{c3::CO₂}} and producing the first {{c3::NADH}}.', cloze_count = 3 WHERE id = '1ec3f46c-e580-4f88-b02e-8f10effaff13';
UPDATE flashcards SET cloze_text = 'Citric acid cycle — Step 4: the {{c1::α-ketoglutarate dehydrogenase complex}} converts {{c1::α-ketoglutarate}} to {{c2::succinyl-CoA}}, releasing the second CO₂ and producing another NADH; this complex is mechanistically analogous to PDH.', cloze_count = 2 WHERE id = '39710621-c670-4dcc-a4a9-0b84acc2feb4';
UPDATE flashcards SET cloze_text = 'Ethanol is converted to acetyl-CoA by {{c1::alcohol dehydrogenase}} (ethanol → {{c2::acetaldehyde}}) followed by {{c2::acetaldehyde dehydrogenase}} ({{c2::acetaldehyde}} → acetate → acetyl-CoA), generating NADH at each step.', cloze_count = 2 WHERE id = '450ade1c-4c95-4f27-8e67-634074487963';
UPDATE flashcards SET cloze_text = '{{c1::Citrate synthase}} is allosterically inhibited by {{c2::ATP}}, {{c2::NADH}}, {{c1::citrate}}, and succinyl-CoA — all signals that energy or downstream products are abundant.', cloze_count = 2 WHERE id = '5921553e-48f2-4a37-9511-c46602e2fbd2';
UPDATE flashcards SET cloze_text = '{{c1::Ketogenic}} amino acids (e.g., leucine, lysine) feed into acetyl-CoA or ketone bodies and {{c2::cannot}} contribute to glucose synthesis; purely {{c1::ketogenic}} AAs are only leucine and lysine.', cloze_count = 2 WHERE id = '62c7e6d1-958c-4480-8084-99568a8d16a1';
UPDATE flashcards SET cloze_text = '{{c1::Glycolysis}} yields {{c2::2 ATP}} directly (substrate-level phosphorylation) plus {{c2::2 NADH}}, contributing ~7 {{c2::ATP}} when those cytosolic {{c2::NADH}} eventually feed the ETC via shuttles.', cloze_count = 2 WHERE id = 'a0fd2a5b-3877-429c-89a1-bb6550523f8d';
UPDATE flashcards SET cloze_text = 'The {{c1::malate-aspartate shuttle}} (preferred by cardiac muscle) transfers cytosolic {{c2::NADH}} electrons to mitochondrial {{c2::NADH}}, which enters at Complex I — yielding the full ~{{c3::2.5 ATP}}.', cloze_count = 3 WHERE id = 'a386135e-58ae-4d94-ba5e-fc4d661c2c41';
UPDATE flashcards SET cloze_text = 'Citric acid cycle — Step 6: {{c1::succinate dehydrogenase}} oxidizes {{c1::succinate}} to fumarate using {{c2::FAD}} (not NAD⁺) — this is the only TCA enzyme embedded in the {{c3::inner mitochondrial membrane}} and is the same as ETC Complex II.', cloze_count = 3 WHERE id = 'c3ea7216-f481-4eee-b00a-c5b2ade8426d';
UPDATE flashcards SET cloze_text = 'From carbohydrates, acetyl-CoA is formed when {{c1::pyruvate}} (the product of glycolysis) is decarboxylated by the {{c1::pyruvate}} {{c2::dehydrogenase complex}} in the mitochondrial matrix.', cloze_count = 2 WHERE id = 'e3337aca-eb6c-4d1a-b779-dc516d2641de';
UPDATE flashcards SET cloze_text = '{{c1::Conformational coupling}} (Boyer''s rotary mechanism) explains how proton flow causes physical rotation of the F₁ subunit, driving {{c1::conformational}} changes that catalyze and release {{c2::ATP}}.', cloze_count = 2 WHERE id = 'ed2d705c-872c-4ee3-9edc-c56ff9c01e87';
-- ── Carbohydrate Structure and Function ──
UPDATE flashcards SET cloze_text = '{{c1::Tollens''}} reagent detects reducing sugars by producing a characteristic {{c2::silver mirror}} as Ag⁺ is reduced to metallic silver by the aldehyde group.', cloze_count = 2 WHERE id = '0a4d605f-1c07-4b5b-bdb3-b1076fc0cbcc';
UPDATE flashcards SET cloze_text = 'A {{c1::lactone}} is a cyclic ester; in carbohydrate chemistry, {{c1::lactones}} form when the anomeric carbon retains its carbonyl character after oxidation.', cloze_count = 1 WHERE id = '33961ffe-4c61-4488-85bf-02558394bd13';
UPDATE flashcards SET cloze_text = 'A molecule with n {{c1::chiral centers}} can have up to {{c2::2ⁿ}} stereoisomers; an aldohexose with 4 {{c1::chiral centers}} thus has 16 total.', cloze_count = 2 WHERE id = '99e0ab66-ff2b-47c7-8ce8-034fa005928b';
-- ── Carboxylic Acid Derivatives ──
UPDATE flashcards SET cloze_text = '{{c1::β-lactams}} are highly reactive because their {{c2::4-membered ring}} suffers both {{c3::angle strain}} (compressed from the ideal 109.5° sp³ bond geometry) and torsional strain from eclipsing interactions.', cloze_count = 3 WHERE id = '0e25f3d5-5145-42d3-955f-e5a09ee26626';
UPDATE flashcards SET cloze_text = '{{c1::Amides}} use the suffix {{c1::-amide}} (replacing -oic acid); alkyl groups on the nitrogen appear as prefixes with the italic letter {{c2::N-}} marking nitrogen substitution.', cloze_count = 2 WHERE id = '25ed79cf-7807-40d1-b368-c54102a53eb4';
UPDATE flashcards SET cloze_text = 'Cyclic amides are called {{c1::lactams}}; the Greek letter names the {{c2::ring size}} — {{c3::β (4-membered), γ (5-membered), δ (6-membered)}}.', cloze_count = 3 WHERE id = 'd0c62f8b-dbb8-47ce-8ddc-73eb7e22d051';
-- ── Carboxylic Acids ──
UPDATE flashcards SET cloze_text = 'The {{c1::carboxylic acid}} derivatives all share a carbonyl with a leaving group attached: {{c1::carboxylic acid}}, {{c1::ester}}, {{c1::amide}}, {{c1::anhydride}}, and {{c1::acyl halide}}.', cloze_count = 1 WHERE id = '096c1bd7-fb3f-441e-a9df-6081a883dd1b';
UPDATE flashcards SET cloze_text = 'IUPAC suffixes for the –COOH group: {{c1::-oic acid}} for linear, {{c1::-carboxylic acid}} for the group attached to a ring, and {{c1::-dioic acid}} for diacids.', cloze_count = 1 WHERE id = '806bffaa-e2f3-41a4-bb89-d673864eaf02';
UPDATE flashcards SET cloze_text = 'For substituent effects on acidity, {{c1::the closer the substituent}} is to the carboxyl group, the {{c2::greater the effect}} on acidity.', cloze_count = 2 WHERE id = '9ffffcee-7100-4690-954a-d6472d540829';
UPDATE flashcards SET cloze_text = 'In {{c1::nucleophilic acyl substitution}}, a nucleophile attacks the {{c2::carbonyl carbon}} to form a {{c3::tetrahedral intermediate}}; the {{c2::carbonyl}} then reforms, kicking off the leaving group.', cloze_count = 3 WHERE id = 'ac396e7e-ca30-445c-b7eb-85e91cb4b18c';
UPDATE flashcards SET cloze_text = '{{c1::Amides}} take the suffix {{c1::-amide}} (replacing -oic acid); alkyl groups on the nitrogen are listed with the prefix {{c2::N-}}. Cyclic {{c1::amides}} are called {{c3::lactams}}.', cloze_count = 3 WHERE id = 'ed3a2750-e58a-426d-9af2-f5534ace0993';
-- ── Cell Division & Human Reproduction ──
UPDATE flashcards SET cloze_text = 'The {{c1::ovaries}} contain thousands of {{c2::follicles}} — multilayered sacs that enclose, nourish, and protect immature ova until ovulation; one dominant {{c2::follicle}} releases its egg per cycle from puberty through menopause.', cloze_count = 2 WHERE id = 'e87bd498-345c-4523-b576-ca6b426745bc';
UPDATE flashcards SET cloze_text = 'Cancer arises when checkpoint genes lose function — mutations in {{c1::TP53}} (the gene encoding {{c1::p53}}) are among the most common drivers because they cripple checkpoint arrest after DNA damage, letting genetically damaged cells continue to divide.', cloze_count = 1 WHERE id = 'eeec6416-d61e-44d7-85cd-f930b8aeae2a';
UPDATE flashcards SET cloze_text = 'The {{c1::follicular phase}} begins as estrogen and progesterone from the previous cycle bottom out, lifting their negative feedback on the hypothalamus; rising {{c2::GnRH}} stimulates the anterior pituitary to release {{c2::FSH}} and {{c2::LH}}, which together recruit ovarian follicles. The growing follicles secrete estrogen that thickens the {{c3::endometrium}} and — early on — suppresses {{c2::GnRH}} via negative feedback.', cloze_count = 3 WHERE id = 'fa6cc5b9-63c7-4f25-8848-955b8b16f21a';
-- ── Chemical Kinetics ──
UPDATE flashcards SET cloze_text = 'A reaction rate is written as a concentration change per unit time; because reactants are consumed, their rate expression carries a {{c1::negative}} sign, while product expressions carry a {{c2::positive}} sign so that the reported rate stays {{c2::positive}}.', cloze_count = 2 WHERE id = '4278ae9e-713d-45fa-b9b1-8ae78158c3f9';
UPDATE flashcards SET cloze_text = 'The Arrhenius equation, k = {{c1::Ae⁻ᴱᵃ⁄ᴿᵀ}}, ties a reaction''s rate constant to its {{c2::activation energy}} and to {{c2::temperature}}.', cloze_count = 2 WHERE id = '49cd4cc7-1e67-403f-9dff-3dd1dc169a54';
UPDATE flashcards SET cloze_text = 'In the rate law rate = k[A]ᵐ[B]ⁿ, the exponents m and n are the {{c1::reaction orders}}, and the overall {{c1::order}} is their {{c2::sum}} — values that must be found {{c3::experimentally}}, never read off the balanced equation''s coefficients.', cloze_count = 3 WHERE id = '638ecc3c-8de1-4fa3-8434-2a4500082ce8';
UPDATE flashcards SET cloze_text = '{{c1::Collision theory}} holds that molecules must physically {{c1::collide}} before they can react, and it predicts the reaction rate is {{c2::proportional to the rate (frequency) of reactant collisions}}.', cloze_count = 2 WHERE id = '8fc570a7-25f3-4e4f-9816-eccc86097aa9';
UPDATE flashcards SET cloze_text = 'When reactants collide with proper orientation and adequate energy they form a short-lived {{c1::activated complex (transition state)}}, which sits at {{c2::higher energy than both the reactants and the products}} on the reaction coordinate.', cloze_count = 2 WHERE id = '982038d5-ba3d-403f-8a11-b7f4f3c59f25';
-- ── Data-Based and Statistical Reasoning ──
UPDATE flashcards SET cloze_text = '{{c1::Correlation does not imply causation}} — to argue {{c1::causation}} from an observed {{c1::correlation}}, evaluate {{c2::Hill''s criteria}} (temporality, dose-response, plausibility, etc.).', cloze_count = 2 WHERE id = '0bda2cb7-7ce9-4ca6-9165-6aafe4d6de60';
UPDATE flashcards SET cloze_text = 'Decision rule: if p < {{c1::α (significance level)}}, {{c2::reject the null}}; if p ≥ {{c1::α}}, {{c2::fail to reject the null}}.', cloze_count = 2 WHERE id = '327c7310-15ba-4a5d-afef-116dc0e95a36';
UPDATE flashcards SET cloze_text = 'A {{c1::box plot}} shows the {{c2::median, Q₁, Q₃, and range}}: the box spans {{c2::Q₁}} to {{c2::Q₃}} with the {{c2::median}} as a line inside, and the whiskers extend to the {{c3::extreme values within 1.5 × IQR}} (outliers plotted separately).', cloze_count = 3 WHERE id = '379b5969-06ef-4e2c-965f-6ff375128565';
UPDATE flashcards SET cloze_text = 'The {{c1::correlation coefficient (r)}} ranges from {{c2::−1 to +1}}: {{c2::−1}} is a perfect negative, {{c2::+1}} is a perfect positive, and {{c3::0}} indicates no apparent linear relationship.', cloze_count = 3 WHERE id = '3b254238-c8c5-4e01-a569-37744bedbac8';
UPDATE flashcards SET cloze_text = 'The empirical rule: in a normal distribution, about {{c1::68%}} of values fall within 1 SD of the mean, about {{c2::95%}} within 2 SD, and about {{c3::99.7%}} within 3 SD.', cloze_count = 3 WHERE id = '3cd67fb7-2515-49d3-8fe3-d2d84e4ae751';
UPDATE flashcards SET cloze_text = 'A {{c1::Type II error}} is failing to reject a {{c2::false null}} — a {{c3::false negative}} — with rate β; statistical {{c1::power}} = {{c2::1 − β}}.', cloze_count = 3 WHERE id = '939f3b9d-247a-49f6-9ec9-3789a924e869';
UPDATE flashcards SET cloze_text = 'A {{c1::bimodal distribution}} has {{c2::two peaks}} with a valley between them; when the {{c2::peaks}} are well-separated, the data are often analyzed as {{c3::two separate distributions}}.', cloze_count = 3 WHERE id = '98d7a7d5-5374-43b3-b5eb-72ca2e3d190d';
UPDATE flashcards SET cloze_text = 'A {{c1::confidence interval}} is a range built from the sample mean ± (a z or t score) × spread; a {{c2::95% confidence level}} is standard, and a wider {{c1::interval}} corresponds to {{c3::higher confidence}}.', cloze_count = 3 WHERE id = 'b3716a40-d921-4f89-868f-0a00f187f291';
UPDATE flashcards SET cloze_text = 'The {{c1::p-value}} is the probability of observing the data (or something more extreme) {{c2::if the null hypothesis is true}}; a smaller {{c1::p-value}} is {{c3::stronger evidence against the null}}.', cloze_count = 3 WHERE id = 'b3e61421-7425-4f17-a3cd-9cf4e2a5a5e6';
UPDATE flashcards SET cloze_text = 'The {{c1::standard deviation (SD)}} measures the average spread of data points around the {{c2::mean}}; it is calculated by squaring each deviation from the {{c2::mean}}, averaging, and taking the {{c3::square root}}.', cloze_count = 3 WHERE id = 'c3870753-c028-457b-a681-92562815ab6a';
UPDATE flashcards SET cloze_text = 'The {{c1::null hypothesis (H₀)}} states that two populations are {{c2::equal}} (or a parameter {{c2::equals}} a given value); it is the statement we attempt to {{c3::reject}}.', cloze_count = 3 WHERE id = 'c6c22e34-7c6f-4ee7-8703-317f98c4b1c1';
UPDATE flashcards SET cloze_text = 'The {{c1::standard normal distribution}} is a bell curve rescaled to have a mean of {{c2::0}} and a standard deviation of {{c3::1}}; any normal data set can be transformed to it.', cloze_count = 3 WHERE id = 'e3128b81-4b9f-4c0f-8216-7e9dfe832bc7';
-- ── Electrochemistry ──
UPDATE flashcards SET cloze_text = 'When {{c1::Keq > 1}}, E°cell is {{c2::positive}}; when {{c1::Keq < 1}}, E°cell is {{c2::negative}}; when {{c1::Keq = 1}}, E°cell equals {{c2::zero}}.', cloze_count = 2 WHERE id = '43024be0-12f8-41f5-b9a2-99abca85c9a9';
UPDATE flashcards SET cloze_text = 'A {{c1::concentration cell}} is a special type of galvanic {{c1::cell}} where the two electrodes are made of the {{c2::same material}}, and the EMF arises from a {{c3::concentration gradient}}.', cloze_count = 3 WHERE id = '43337875-617f-404d-bff0-436cd28020ad';
UPDATE flashcards SET cloze_text = 'The salt bridge also serves to {{c1::close the electrical circuit}} — without it, the redox reaction quickly stops, and the cell cannot deliver electrical energy.', cloze_count = 1 WHERE id = '53aca552-faf0-4493-8a3c-96321d975c61';
UPDATE flashcards SET cloze_text = 'In any electrochemical cell, {{c1::ΔG}} and {{c1::EMF}} always have opposite signs: {{c1::ΔG}} < 0 (favorable) ↔ {{c1::EMF}} > 0; {{c1::ΔG}} > 0 (unfavorable) ↔ {{c1::EMF}} < 0.', cloze_count = 1 WHERE id = '575e365b-1bf6-4505-8b32-ae9cc835fd8a';
UPDATE flashcards SET cloze_text = 'Quick summary: {{c1::galvanic}} cells convert chemical energy to {{c2::electrical energy}}; {{c1::electrolytic}} cells convert {{c2::electrical energy}} to chemical energy — they are opposite-direction processes.', cloze_count = 2 WHERE id = '5b196e29-ee0f-4917-b107-f9ecd3617ee3';
UPDATE flashcards SET cloze_text = 'A {{c1::lead-acid battery}} ({{c1::lead storage battery}}) has a {{c2::Pb}} (lead) anode and a porous {{c2::PbO₂}} (lead(IV) oxide) cathode, both immersed in concentrated {{c3::H₂SO₄}}.', cloze_count = 3 WHERE id = 'aac8037c-7b0a-4356-94fd-cd405da6e988';
UPDATE flashcards SET cloze_text = '{{c1::Energy density}} is the amount of energy a battery can store per unit {{c2::mass}} (or volume); higher {{c1::energy density}} means more energy from a lighter or smaller battery.', cloze_count = 2 WHERE id = 'cc179ea5-7f57-4b8e-8bbb-598f8b32b0e1';
UPDATE flashcards SET cloze_text = 'Faraday''s laws of electrolysis: (1) mass deposited is proportional to total {{c1::charge}} passed; (2) for equal {{c1::charges}}, mass deposited depends on the {{c2::equivalent weight}} of the species (M/n).', cloze_count = 2 WHERE id = 'ddef93c2-56db-46f4-9a89-48de0fcbe35d';
UPDATE flashcards SET cloze_text = 'In a {{c1::galvanic}} cell, the {{c2::anode}} carries the {{c3::negative (−)}} sign and the {{c2::cathode}} carries the positive (+) sign — electrons leave the {{c2::anode}} and flow to the {{c2::cathode}}.', cloze_count = 3 WHERE id = 'e9ce851d-d1d7-481c-882c-467a112cf17a';
-- ── Embryonic Development & Gestation ──
UPDATE flashcards SET cloze_text = '{{c1::Fetal hemoglobin (HbF)}} has higher oxygen affinity than adult hemoglobin (HbA), enabling efficient {{c2::oxygen transfer}} from maternal to {{c1::fetal}} blood across the placenta.', cloze_count = 2 WHERE id = '2c052d24-98e6-49fb-86c6-2ed07a936d6e';
UPDATE flashcards SET cloze_text = 'The fetal {{c1::liver}} is immature, so the {{c1::maternal liver}} detoxifies most metabolic waste; nitrogenous wastes diffuse from fetal blood into {{c1::maternal}} blood at the placenta.', cloze_count = 1 WHERE id = '8782f13c-b9e3-4f06-84d0-ee257786fad4';
UPDATE flashcards SET cloze_text = 'A {{c1::morphogen}} is a signaling molecule that forms a concentration {{c2::gradient}} across a tissue, and different concentrations specify different cell fates along the {{c2::gradient}}.', cloze_count = 2 WHERE id = 'b5422e41-8fa6-4cbf-8185-5b1f0f23b009';
UPDATE flashcards SET cloze_text = '{{c1::Totipotent}} cells can give rise to any cell type in the embryo and to the {{c2::extraembryonic}} tissues (placenta). Only the zygote and the earliest cleavage cells are truly {{c1::totipotent}}.', cloze_count = 2 WHERE id = 'c3506005-91e7-43b0-b733-b81597e65142';
UPDATE flashcards SET cloze_text = 'The cortical reaction generates the {{c1::fertilization membrane}}, an electrochemically modified outer layer that prevents {{c2::polyspermy}} (entry of more than one sperm).', cloze_count = 2 WHERE id = 'cb5e6bf8-d6b5-4ac0-bcea-0565ec3d79f8';
UPDATE flashcards SET cloze_text = 'In {{c1::induction}}, a signaling cell (the inducer) releases a molecule that directs the fate of a neighboring {{c2::responder}} cell — but only if the {{c2::responder}} has the appropriate {{c3::competence}} to receive the signal.', cloze_count = 3 WHERE id = 'd0ff3861-6842-49ba-b663-d54026eaf06b';
UPDATE flashcards SET cloze_text = 'After fertilization the zygote undergoes {{c1::cleavage}}, a rapid series of mitotic divisions with no overall growth. The first {{c1::cleavage}} marks the official start of the {{c2::embryo}}.', cloze_count = 2 WHERE id = 'd30dc930-ac21-4c39-964a-02b646117f6e';
UPDATE flashcards SET cloze_text = '{{c1::Pluripotent}} cells can give rise to any cell of the three {{c2::germ layers}} but cannot form extraembryonic tissue. The inner cell mass of the blastocyst is {{c1::pluripotent}}.', cloze_count = 2 WHERE id = 'f383877c-ceac-4f10-b308-25d8a7f0ec58';
UPDATE flashcards SET cloze_text = 'In {{c1::paracrine}} signaling, the released molecule diffuses to and acts on {{c2::nearby cells}}; many developmental signals (e.g., growth factors) are {{c1::paracrine}}.', cloze_count = 2 WHERE id = 'fdbf515a-a1da-4b48-bdf8-2db186192c1c';
-- ── Energy, Work & Simple Machines ──
UPDATE flashcards SET cloze_text = 'A {{c1::non-conservative force}} is one whose work is {{c2::path-dependent}} — more work is required along a longer route than a shorter one between the same two endpoints. {{c1::Non-conservative forces}} {{c3::dissipate}} mechanical energy, usually converting it to heat.', cloze_count = 3 WHERE id = '0672961b-50e4-4c75-89d1-381977881f8b';
UPDATE flashcards SET cloze_text = 'The {{c1::efficiency}} of a real machine is the ratio of its useful work output to the work input, usually expressed as a percentage: {{c2::Efficiency = (Wout / Win) × 100%}}. For an ideal frictionless machine, {{c1::efficiency}} = 100%; real machines are always less.', cloze_count = 2 WHERE id = '0d9846de-b7f2-4020-9825-f839f31b582b';
UPDATE flashcards SET cloze_text = '{{c1::Average}} power is the total work divided by the total time interval (W/Δt). {{c2::Instantaneous}} power is the limit as Δt → 0 — the rate of work at a specific moment. {{c1::Average}} and {{c2::instantaneous}} power are equal only when the power delivered is {{c3::constant}} throughout the interval.', cloze_count = 3 WHERE id = '1522a26b-ae0c-4518-b8fb-d0a32d638993';
UPDATE flashcards SET cloze_text = 'Energy is the capacity of a system to {{c1::do work}} or bring about change. Its SI unit is the {{c2::joule (J)}}, which is also the unit of {{c1::work}} — both measure the same physical quantity expressed in base units as {{c3::kg·m²/s²}}.', cloze_count = 3 WHERE id = '184cbb26-087e-4b7c-b402-ed6e0a804585';
UPDATE flashcards SET cloze_text = 'Conservation of {{c1::mechanical}} energy is a special case requiring no non-conservative forces. The broader principle — the {{c2::first law of thermodynamics}} — states that {{c3::total energy (mechanical + thermal + chemical + …)}} of an isolated system is always conserved, even when {{c1::mechanical}} energy alone is not.', cloze_count = 3 WHERE id = '18d7c47c-f201-4574-8211-ca66b7da2b60';
UPDATE flashcards SET cloze_text = '{{c1::Work}} is the mechanism by which energy is transferred between systems through the application of a force over a distance. Its SI unit is the {{c2::joule}} — the same unit as energy, reflecting the fact that {{c1::work}} IS energy in transit.', cloze_count = 2 WHERE id = '610bc648-7aea-48a4-802f-8472da054e75';
UPDATE flashcards SET cloze_text = 'To test whether a force is {{c2::conservative}}: have the object traverse a {{c1::closed loop}} back to its starting position. If the system returns with the same mechanical energy it started with, the force is {{c2::conservative}}; if it has lost energy, the force is {{c3::non-conservative}}.', cloze_count = 3 WHERE id = '7dfb8484-5df0-440b-8716-d1407348f4d1';
UPDATE flashcards SET cloze_text = 'The work-energy theorem (Wnet = ΔK) relates net work to {{c1::kinetic energy only}} — not potential, not {{c2::total mechanical}} energy. By contrast, the broader energy-conservation principle (ΔE = Wnc when E = K + U) relates non-conservative work to {{c2::total mechanical}} energy.', cloze_count = 2 WHERE id = 'b8069e98-a273-4f4b-90b7-ed4ffead0341';
UPDATE flashcards SET cloze_text = 'When {{c1::non-conservative}} forces act, mechanical energy is generally lost. The work done by {{c1::non-conservative}} forces equals the {{c2::change in total mechanical energy}}: Wnc = ΔE = ΔK + ΔU (typically negative when friction or drag dissipates energy).', cloze_count = 2 WHERE id = 'bd932b52-10d8-4caf-ac55-76f6ca3eb1f3';
UPDATE flashcards SET cloze_text = 'For a gas undergoing a thermodynamic process, the {{c2::work}} done equals the {{c1::area under the curve}} on a pressure-vs-volume (P-V) graph. The exact area depends on the path taken, so different processes between the same two endpoints can do {{c2::different amounts of work}}.', cloze_count = 2 WHERE id = 'be92a55c-e4e6-4e46-b835-00a6bef04c16';
UPDATE flashcards SET cloze_text = '{{c1::Power}} is the rate at which energy is transferred or work is done: {{c2::P = W/t = ΔE/t}}. {{c1::Power}} tells you how *fast* a given amount of work is accomplished — a more {{c1::powerful}} engine does the same amount of work in less time.', cloze_count = 2 WHERE id = 'cbb56bc6-3bc5-4b74-84fd-8a6eb681b86e';
UPDATE flashcards SET cloze_text = 'A {{c1::conservative force}} is one whose work depends only on the {{c2::start and end positions}}, not on the path taken between them. Equivalently: when an object traverses a closed loop and returns to its starting point, a {{c1::conservative force}} does {{c3::zero net work}}.', cloze_count = 3 WHERE id = 'ce768eee-70e9-4234-a3f8-90cba9c86089';
-- ── Enzymes ──
UPDATE flashcards SET cloze_text = '{{c1::Vmax}} is the maximum reaction rate reached when every active site is saturated with substrate; the only way to raise {{c1::Vmax}} is to increase {{c2::enzyme concentration}}.', cloze_count = 2 WHERE id = '01622ae1-7d21-4083-80eb-296abdd9a64c';
UPDATE flashcards SET cloze_text = '{{c1::Feedback inhibition}} (negative {{c1::feedback}}) occurs when the end product of a metabolic pathway inhibits an enzyme {{c2::earlier in the same pathway}}, conserving resources once the product accumulates.', cloze_count = 2 WHERE id = '1b606192-67f5-4bb5-9f09-d91260a868ff';
UPDATE flashcards SET cloze_text = '{{c1::Allosteric enzymes}} have at least one regulatory ({{c2::allosteric}}) site distinct from the active site; ligand binding at the {{c2::allosteric}} site shifts the enzyme between active and inactive conformations.', cloze_count = 2 WHERE id = '1fb846ff-521b-4247-ad51-8ac00e54ff7c';
UPDATE flashcards SET cloze_text = '{{c1::Isomerases}} rearrange bonds within a single molecule to interconvert {{c2::isomers}}, including stereo- and constitutional {{c2::isomers}}.', cloze_count = 2 WHERE id = '33b0cad1-7509-4f88-b8f3-53e85303758b';
UPDATE flashcards SET cloze_text = '{{c1::Enzyme specificity}} means that each enzyme catalyzes only a particular reaction or a particular class of reaction acting on its {{c1::specific}} {{c2::substrate(s)}}.', cloze_count = 2 WHERE id = '600ddce3-28a1-47ed-9ab4-66dd3e107961';
UPDATE flashcards SET cloze_text = 'Many enzymes are named for what they do: a {{c1::cyclase}} makes cyclic molecules (e.g., adenylate {{c1::cyclase}} makes cAMP), a {{c2::phosphatase}} removes phosphates, and an {{c3::acetylase}} adds acetyl groups.', cloze_count = 3 WHERE id = '61e80e40-5606-436e-8f2e-36839f917974';
UPDATE flashcards SET cloze_text = 'Common organic coenzymes derived from vitamins include {{c1::NAD⁺}}, {{c1::FAD}}, and {{c1::coenzyme A}}; they shuttle electrons or functional groups between reactions.', cloze_count = 1 WHERE id = '6d0558c0-8aca-48ce-baab-d53b20af0b40';
UPDATE flashcards SET cloze_text = '{{c1::Catalytic efficiency}} is given by the ratio {{c2::kcat / Km}}; a high {{c2::kcat}} (fast turnover) or low {{c2::Km}} (tight binding) both increase it.', cloze_count = 2 WHERE id = '9c43199d-e5c4-4fad-847d-dab11e3dfea7';
UPDATE flashcards SET cloze_text = '{{c1::kcat}} can be calculated from {{c1::Vmax}} using {{c1::kcat = Vmax / [E]total}}, where {{c1::[E]total}} is the total enzyme concentration.', cloze_count = 1 WHERE id = 'e929b270-cbaa-44ce-98fd-46dd6dcbbcd9';
-- ── Equilibrium ──
UPDATE flashcards SET cloze_text = 'A {{c1::large}} Keq means the equilibrium mixture is dominated by {{c2::products}}, with the forward reaction proceeding nearly to completion, whereas a {{c1::small}} Keq means little conversion has occurred and {{c2::reactants}} predominate.', cloze_count = 2 WHERE id = '16bcfdfd-2e4f-46cf-a189-87eee625e05e';
UPDATE flashcards SET cloze_text = 'For temperature stresses, heat is treated as a {{c1::reactant}} in an endothermic reaction (ΔH > 0) and as a {{c1::product}} in an exothermic reaction (ΔH < 0).', cloze_count = 1 WHERE id = '4eb7e4ec-f2ed-4ea8-8d46-4f43e3dc4208';
UPDATE flashcards SET cloze_text = 'The law of mass action states that at a given {{c1::temperature}}, the reaction quotient for a system at equilibrium has a {{c2::constant}} value, which is called the equilibrium {{c2::constant}} K.', cloze_count = 2 WHERE id = '95e81b45-3ad3-46ba-a97c-d45f70d5ad62';
UPDATE flashcards SET cloze_text = 'Adding a {{c2::reactant}} or removing a {{c1::product}} shifts an equilibrium toward the {{c1::products (forward, right)}}, whereas removing a {{c2::reactant}} or adding a {{c1::product}} shifts it toward the {{c2::reactants (reverse, left)}}.', cloze_count = 2 WHERE id = 'a40381d0-252e-46e4-90b4-6fcf50f273fd';
UPDATE flashcards SET cloze_text = 'The value of Keq depends on {{c1::temperature}}, so it changes only when the {{c1::temperature}} changes; adding reactant or product, or adding a catalyst, leaves Keq {{c2::unchanged}}.', cloze_count = 2 WHERE id = 'b5e743ab-ee81-4c20-aeda-fffa9cc0a4fa';
UPDATE flashcards SET cloze_text = 'Le Châtelier''s principle states that when a system at equilibrium is subjected to a {{c1::stress}}, the equilibrium {{c2::shifts}} in the direction that relieves the {{c1::stress}} and re-establishes equilibrium.', cloze_count = 2 WHERE id = 'bdb826bb-9955-489e-b3c3-8febb6b3b77e';
-- ── Genetics and Evolution ──
UPDATE flashcards SET cloze_text = '{{c1::Inbreeding}} (mating between close relatives) increases {{c2::homozygosity}} and exposes rare recessive disease alleles; the resulting drop in population fitness is called {{c1::inbreeding}} {{c3::depression}}.', cloze_count = 3 WHERE id = '170e65ea-9094-41c7-961c-395dd569c664';
UPDATE flashcards SET cloze_text = 'The {{c1::founder effect}} is an extreme case of genetic drift: a small group becomes reproductively isolated, so the new population''s gene pool reflects only the {{c1::founders''}} alleles.', cloze_count = 1 WHERE id = '378ad6e0-43e1-4d4c-a836-78573cbb5238';
UPDATE flashcards SET cloze_text = '{{c1::Expressivity}} describes the {{c2::variability}} in phenotype severity among individuals who share the same genotype; constant {{c1::expressivity}} gives identical phenotypes, variable {{c1::expressivity}} does not.', cloze_count = 2 WHERE id = '4007dd69-739a-4a36-a3f1-0cc4443cc8a2';
UPDATE flashcards SET cloze_text = 'Genotypic {{c2::males}} are {{c1::hemizygous}} for X-linked genes — they carry only one X — which is why X-linked recessive disorders (e.g., hemophilia, color-blindness) are far more common in {{c2::males}}.', cloze_count = 2 WHERE id = '43f22dfe-a383-460d-b6b2-2b4d2f036ada';
UPDATE flashcards SET cloze_text = 'A {{c1::point mutation}} changes a single nucleotide in DNA; because a {{c2::codon}} is a three-nucleotide unit, the effect depends on whether the {{c2::codon}}''s amino acid still gets coded correctly.', cloze_count = 2 WHERE id = '55a7913f-96da-46e4-b3f3-dfafd8cc320c';
UPDATE flashcards SET cloze_text = 'An {{c1::allele}} is one of the alternative versions of a given gene; humans inherit two {{c1::alleles}} per gene — one from each parent.', cloze_count = 1 WHERE id = '5ee77819-78a5-4c76-9633-de037f090cda';
UPDATE flashcards SET cloze_text = 'The {{c1::gene pool}} of a species is the complete set of all alleles present across every individual; greater diversity in the {{c1::gene pool}} improves the species'' ability to {{c2::adapt}}.', cloze_count = 2 WHERE id = '696d0a89-8325-4675-8be6-ed7e3d8bf66e';
UPDATE flashcards SET cloze_text = 'The {{c1::genotype}} is the specific combination of alleles an individual carries; the {{c1::phenotype}} is the observable expression of that {{c1::genotype}}.', cloze_count = 1 WHERE id = 'cf1d4f26-6cf0-4b45-abfe-f94d8d31d42f';
UPDATE flashcards SET cloze_text = 'The law of independent assortment corresponds to {{c1::metaphase I}}, when homologous chromosome pairs align on the {{c1::metaphase}} plate in random orientations.', cloze_count = 1 WHERE id = 'deda324e-2903-4eb5-ba01-8e954d5caf34';
UPDATE flashcards SET cloze_text = 'A {{c1::species}} is the largest group of organisms that can interbreed to produce {{c2::fertile, viable}} offspring; this is the biological {{c1::species}} concept.', cloze_count = 2 WHERE id = 'fd638821-d73e-46bf-b54c-6f8070a89490';
-- ── Inside the Atom ──
UPDATE flashcards SET cloze_text = 'In the {{c1::Bohr model}} of the hydrogen atom, a single electron travels around the central proton in {{c2::quantized circular orbits}}; only specific {{c2::orbits}} are allowed, each corresponding to a discrete energy.', cloze_count = 2 WHERE id = '0cf7561b-dcae-4b0f-9923-86891c6e76df';
UPDATE flashcards SET cloze_text = 'The {{c1::principal quantum number (n)}} labels the shell of an electron; it takes positive integer values starting at 1, and the {{c2::larger}} n is, the {{c2::higher}} the electron''s energy and the {{c2::larger}} its average distance from the nucleus.', cloze_count = 2 WHERE id = '76ceea76-ef7d-47be-9712-c96fb01334ba';
UPDATE flashcards SET cloze_text = 'A {{c1::mole}} is the number of items equal to {{c2::Avogadro''s number, 6.022 × 10²³}}; one {{c1::mole}} of an element has a mass in grams numerically equal to its atomic weight in amu.', cloze_count = 2 WHERE id = '8c65ff06-6210-4838-b16e-af9af79c0f46';
UPDATE flashcards SET cloze_text = 'Every element''s {{c1::absorption spectrum}} is the {{c2::mirror image}} of its emission spectrum — the wavelengths {{c1::absorbed}} are exactly those the same atom would emit, because the energy gaps between levels are the same in either direction.', cloze_count = 2 WHERE id = '8d89758f-bc92-4737-a11c-66ff532a9d77';
UPDATE flashcards SET cloze_text = 'The {{c1::atomic mass}} of a specific atom is measured in {{c2::daltons (amu)}} and is approximately equal to its mass number — the sum of protons and neutrons.', cloze_count = 2 WHERE id = '99e82a84-458e-4aad-ba03-2345b7a9ef96';
UPDATE flashcards SET cloze_text = 'The {{c1::atomic weight}} listed on the periodic table is the {{c2::weighted average}} of the masses of an element''s naturally occurring isotopes — scaled by relative abundance, which is why most are non-integer values.', cloze_count = 2 WHERE id = 'd1545cf6-7c62-45fd-a421-04e7ac49da33';
-- ── Isomerism & Stereochemistry ──
UPDATE flashcards SET cloze_text = 'Isomers — molecules sharing the same molecular formula — divide into two broad classes: {{c1::structural (constitutional) isomers}} differ in {{c2::atomic connectivity}}, while {{c3::stereoisomers}} share {{c2::connectivity}} but differ in {{c4::spatial arrangement}}.', cloze_count = 4 WHERE id = '1d656e25-e5ca-42a3-afec-f56a604ddd9e';
UPDATE flashcards SET cloze_text = 'Two structural isomers can have identical molecular formulas yet behave entirely differently in the lab — different boiling points, different reactivities — because their atoms are bonded in {{c1::different patterns}}, producing different functional groups, branch arrangements, or ring structures.', cloze_count = 1 WHERE id = '6b639a6e-dd33-4503-a839-cb604ef9d3d7';
UPDATE flashcards SET cloze_text = 'Three distinct strain types contribute to the instability of cyclic conformations: {{c1::angle strain}} (bonds forced to deviate from their ideal geometry), {{c2::torsional strain}} (eclipsing interactions on adjacent carbons), and {{c3::non-bonded (van der Waals) strain}} (atoms competing for the same space).', cloze_count = 3 WHERE id = '6be178c0-f513-4c7a-83cf-597458fa6d9c';
UPDATE flashcards SET cloze_text = 'An object is {{c1::chiral}} if its mirror image cannot be superimposed on the original — your two hands are the canonical example. A molecule is {{c1::chiral}} if and only if it lacks an {{c2::internal plane of symmetry}}.', cloze_count = 2 WHERE id = '7ef715f8-c8d7-4906-b479-c691d88f46e2';
UPDATE flashcards SET cloze_text = 'Enantiomers have {{c1::identical}} physical and chemical properties with two important exceptions: they rotate {{c2::plane-polarized light}} in opposite directions, and they react differently in {{c3::chiral environments}} (such as enzyme active sites or other {{c3::chiral}} reagents).', cloze_count = 3 WHERE id = '8172070f-f864-4e24-a555-147d1c77dea2';
UPDATE flashcards SET cloze_text = 'Stereoisomers further split into {{c1::conformational}} isomers (interconvertible by rotation around single bonds — same molecule in different orientations) and {{c2::configurational}} isomers (interconvertible only by {{c3::breaking and re-forming covalent bonds}}). Enantiomers and diastereomers are {{c2::configurational}}.', cloze_count = 3 WHERE id = '8218e45f-abd5-4e5e-9348-4b72916dc9f3';
UPDATE flashcards SET cloze_text = '{{c1::Configurational isomers}} share the same connectivity but differ in their spatial arrangement in a way that cannot be undone by rotation alone — converting one to the other requires {{c2::breaking and re-forming covalent bonds}}. Enantiomers, diastereomers, and cis/trans isomers are all {{c1::configurational}}.', cloze_count = 2 WHERE id = '89965f67-ea31-41e1-8fc4-6f13d6fa31c9';
UPDATE flashcards SET cloze_text = 'A {{c1::chiral center}} (stereocenter) is a carbon bonded to {{c2::four different substituents}}. Any carbon with even two identical groups is automatically achiral at that position because the molecule contains a plane of symmetry through it.', cloze_count = 2 WHERE id = '9c84024a-2c04-4e6a-9145-2e63ad7a8fef';
UPDATE flashcards SET cloze_text = 'Under {{c1::Cahn-Ingold-Prelog (CIP) priority rules}}, substituents on a chiral center or double-bonded carbon are ranked by the {{c2::atomic number}} of the atoms directly attached — higher {{c2::atomic number}} = higher priority. Ties are broken by working {{c3::outward}}, comparing the next atoms one bond further until a difference is found.', cloze_count = 3 WHERE id = 'a4044556-1a0f-46cc-9619-b25a6ce04b29';
UPDATE flashcards SET cloze_text = 'The {{c1::boat}} conformation of cyclohexane suffers from {{c2::flagpole interactions}} — the two carbons at the bow and stern of the {{c1::boat}} point their axial substituents directly at each other, generating significant non-bonded strain. The twist-{{c1::boat}} partially relieves this but is still far less stable than the chair.', cloze_count = 2 WHERE id = 'aa1a6498-1aaf-4c97-9412-8e6c8fe797f9';
UPDATE flashcards SET cloze_text = 'A {{c1::physical property}} can be observed or measured without changing its composition (melting point, boiling point, density, solubility, color, odor). A {{c2::chemical property}} describes how a substance {{c3::reacts}} with other species — by definition, observing it changes the composition.', cloze_count = 3 WHERE id = 'ca5ce960-5ed3-444f-b5c3-7f7c78e0ae83';
UPDATE flashcards SET cloze_text = '{{c1::Conformational isomers (conformers)}} are the same molecule observed at different rotational positions around a {{c2::single (σ) bond}}; because rotation around a {{c2::single bond}} is essentially free at room temperature, conformers rapidly interconvert without breaking any bonds.', cloze_count = 2 WHERE id = 'cae193a3-6be2-4cae-9b89-d0a7be00a3f9';
UPDATE flashcards SET cloze_text = 'In a substituted cyclic compound, two substituents are {{c1::cis}} if they are on the {{c2::same side}} (same face) of the ring plane and {{c1::trans}} if they are on {{c2::opposite sides}} — this is a true configurational distinction because converting {{c1::cis}} to {{c1::trans}} would require breaking and reforming a covalent bond.', cloze_count = 2 WHERE id = 'ec7aceb7-3ebf-41cd-b217-833db56f00d4';
-- ── Lipid and Amino Acid Metabolism ──
UPDATE flashcards SET cloze_text = '{{c1::HMG-CoA reductase}} catalyzes the rate-limiting step of cholesterol biosynthesis ({{c1::HMG-CoA}} → {{c2::mevalonate}}) in the smooth endoplasmic reticulum; statins inhibit this enzyme.', cloze_count = 2 WHERE id = '066457bb-45a0-419c-b1fb-c4fbb6065848';
UPDATE flashcards SET cloze_text = 'HMG-CoA reductase is feedback-inhibited by {{c1::cholesterol}} itself and activated by {{c2::insulin}}, making {{c1::cholesterol}} synthesis most active in the well-fed state.', cloze_count = 2 WHERE id = '087da441-cfeb-4a29-807f-c4c8a2aaf9cd';
UPDATE flashcards SET cloze_text = 'Lipoproteins are synthesized primarily by the {{c1::liver}} and the {{c1::intestine}}; chylomicrons originate in the {{c1::intestine}} and the others (VLDL, HDL) originate in the {{c1::liver}}.', cloze_count = 1 WHERE id = '2106f62c-1130-4b23-8e24-cd161fd8904d';
UPDATE flashcards SET cloze_text = 'For cholesterol (and fatty acid) synthesis, mitochondrial acetyl-CoA must reach the cytosol — it is transported as {{c1::citrate}}, which is then split back to acetyl-CoA by {{c1::citrate}} {{c2::lyase}}.', cloze_count = 2 WHERE id = '327d36a1-ed50-4ace-8fc1-c99e8084fb08';
UPDATE flashcards SET cloze_text = '{{c1::Hormone-sensitive lipase (HSL)}} works inside {{c2::adipocytes}} to mobilize stored fat; {{c1::lipoprotein lipase (LPL)}} works on the surface of {{c2::blood vessel endothelium}} to release fatty acids from circulating triglyceride-rich particles.', cloze_count = 2 WHERE id = '7ef7bb98-09f0-4a25-9eb9-97aaab4a38b7';
UPDATE flashcards SET cloze_text = 'Emulsification is driven by {{c1::bile}}, a fluid containing {{c1::bile}} salts, cholesterol, and pigments; {{c1::bile}} is made by the {{c2::liver}} and stored in the {{c3::gallbladder}}.', cloze_count = 3 WHERE id = '9a403382-95b9-4922-86d8-e47ef3b778d7';
UPDATE flashcards SET cloze_text = '{{c1::Propionyl-CoA}} is carboxylated by {{c1::propionyl-CoA}} carboxylase (using {{c2::biotin}}) to methylmalonyl-CoA, which is then converted to {{c3::succinyl-CoA}} by a vitamin B₁₂-dependent mutase.', cloze_count = 3 WHERE id = 'bd1fb2d5-2b02-4e45-8a06-a4b780b0a6c5';
UPDATE flashcards SET cloze_text = '{{c1::CETP (cholesteryl ester transfer protein)}} {{c1::transfers cholesteryl esters}} from HDL to other lipoproteins like IDL — converting IDL into {{c2::LDL}} in the process.', cloze_count = 2 WHERE id = 'c169a43b-a39a-4730-b4f4-9a6e93201213';
UPDATE flashcards SET cloze_text = '{{c1::VLDL (very-low-density lipoprotein)}} is made in the {{c2::liver}} and transports triacylglycerols and fatty acids from the {{c2::liver}} to peripheral tissues.', cloze_count = 2 WHERE id = 'c273b5a0-39b2-49b5-802b-dea9567bd38a';
UPDATE flashcards SET cloze_text = 'Fatty acid {{c1::synthase}} (also called {{c1::palmitate synthase}}) cycles eight times, using {{c2::8 acetyl-CoA}} units to produce a 16-carbon saturated fatty acid: {{c3::palmitate}} — the only fatty acid humans can synthesize de novo.', cloze_count = 3 WHERE id = 'd71fd653-8e10-4c73-b5b6-65e208bbadc2';
UPDATE flashcards SET cloze_text = 'Each cycle of fatty acid synthesis follows five steps: {{c1::activation}}, {{c1::bond formation}}, {{c1::reduction}}, {{c1::dehydration}}, and a {{c1::second reduction}}.', cloze_count = 1 WHERE id = 'f2e6f49a-f605-4a13-a7c0-c96f0cbd2a91';
-- ── Mathematics ──
UPDATE flashcards SET cloze_text = 'SOH CAH TOA — sin θ = {{c1::opposite}} / {{c2::hypotenuse}}; cos θ = {{c1::adjacent}} / {{c2::hypotenuse}}; tan θ = {{c1::opposite}} / {{c1::adjacent}}.', cloze_count = 2 WHERE id = 'f48de5ec-ee4f-45c2-ab68-c01916fd6519';
-- ── Motion & Forces ──
UPDATE flashcards SET cloze_text = 'In real free fall through air, an object also experiences a {{c1::drag force}} that grows with speed. When {{c1::drag}} balances weight, the net force is zero and the object continues at a constant speed called the {{c2::terminal velocity}}.', cloze_count = 2 WHERE id = '0fbd4c2c-f03b-47f2-b385-abb3b57b666e';
UPDATE flashcards SET cloze_text = 'An {{c1::electron volt (eV)}} is the energy an {{c1::electron}} gains when accelerated through a potential difference of {{c2::one volt}}; it is the practical energy unit at the atomic scale, where the joule is too large.', cloze_count = 2 WHERE id = '1494ae7f-5af2-4c84-b358-14a48b211624';
UPDATE flashcards SET cloze_text = 'Average velocity is the {{c1::displacement divided by elapsed time}}: v̄ = {{c1::Δx/Δt}}. Its direction matches the direction of the {{c1::displacement}} vector.', cloze_count = 1 WHERE id = '2076aa69-76d6-4598-8055-c376f64c9261';
UPDATE flashcards SET cloze_text = 'The {{c1::cross product (vector product)}} of two vectors yields a new {{c2::vector}} whose magnitude is |A||B|sin θ. The resulting {{c2::vector}} is always {{c3::perpendicular to the plane}} containing the two input vectors. Torque — the {{c1::cross product}} of position and force — is the classic example.', cloze_count = 3 WHERE id = '27461a49-8ea5-440a-b4c7-9f0ca6ab19cb';
UPDATE flashcards SET cloze_text = 'The {{c1::torque}} produced by a force applied at distance r from the pivot is τ = {{c2::rF sin θ}}, where θ is the angle between the lever arm and the force vector. {{c1::Torque}} is the {{c3::cross product}} of the position vector and the force vector.', cloze_count = 3 WHERE id = '32c0e3b0-487b-472b-83c2-626ea2cfc694';
UPDATE flashcards SET cloze_text = '{{c1::Friction}} is a contact force that opposes the {{c2::relative motion (or attempted relative motion)}} of surfaces in contact; it arises from microscopic interactions between the two surfaces. {{c1::Friction}} always points along the contact surface, never perpendicular to it.', cloze_count = 2 WHERE id = '363029e7-763a-43e3-93e2-11f0424f1b35';
UPDATE flashcards SET cloze_text = 'Because no {{c1::horizontal}} force acts on a projectile (ignoring air resistance), the {{c1::horizontal velocity remains constant}} throughout the flight. Only the {{c2::vertical}} velocity changes — by g (≈ 9.8 m/s²) downward each second.', cloze_count = 2 WHERE id = '3757167c-57e0-4777-9cbe-6c52a4efefd9';
UPDATE flashcards SET cloze_text = 'On a planet, the weight of an object is given by {{c1::W = mg}}, where m is the object''s mass and g is the {{c2::local acceleration due to gravity}} (≈ 9.8 m/s² on Earth''s surface). Note: lowercase g is {{c2::acceleration}}; uppercase G is the universal gravitational constant — they are different quantities.', cloze_count = 2 WHERE id = '3d1ef3c2-2897-4e93-8371-7b515573baaf';
UPDATE flashcards SET cloze_text = 'By standard convention, torques producing {{c1::counterclockwise}} rotation are taken as {{c2::positive}}, and torques producing {{c1::clockwise}} rotation are taken as {{c2::negative}}. In rotational equilibrium, the {{c2::positive}} and {{c2::negative}} torques cancel exactly.', cloze_count = 2 WHERE id = '4576013d-9ecd-41f9-91d4-b288c7de9fc5';
UPDATE flashcards SET cloze_text = 'Any vector can be {{c1::resolved into perpendicular components}} (typically along the x- and y-axes); these {{c1::components}} carry signs (positive or negative) indicating which way along each axis the vector points.', cloze_count = 1 WHERE id = '666084f3-dc06-4fb4-8c91-7e1ae4902a9b';
UPDATE flashcards SET cloze_text = 'In the {{c1::tip-to-tail method}}, vectors are added graphically by moving each successive vector so its {{c2::tail starts at the previous vector''s tip}}, keeping all magnitudes and directions intact. The {{c3::resultant vector}} then connects the very first {{c2::tail}} to the very last {{c2::tip}}.', cloze_count = 3 WHERE id = '67eb7343-55b4-4f4f-bd4a-d6d713d2c6a8';
UPDATE flashcards SET cloze_text = 'A {{c1::force}} is any push or pull that can cause an object to accelerate. {{c1::Force}} is a {{c2::vector}}, and its SI unit is the {{c3::newton (N) = kg·m/s²}}.', cloze_count = 3 WHERE id = '831f8c46-a51b-487a-81d1-a91d33ebf17b';
UPDATE flashcards SET cloze_text = '{{c1::Instantaneous velocity}} is the limit of average velocity as Δt approaches zero; geometrically, it is the {{c2::slope of the position-vs-time graph}} at that moment.', cloze_count = 2 WHERE id = '8725af42-27a5-475f-a890-57575601b339';
UPDATE flashcards SET cloze_text = 'In projectile motion (2D motion under gravity alone), the horizontal and {{c2::vertical}} motions are mathematically {{c1::independent}}. Gravity acts only along the {{c2::vertical}} axis, while no force acts along the horizontal axis (with air resistance neglected).', cloze_count = 2 WHERE id = '891a9211-2550-4e39-9d1e-959aa7201a6d';
UPDATE flashcards SET cloze_text = 'The {{c1::dot product (scalar product)}} of two vectors yields a {{c2::scalar}}: A·B = |A||B|cos θ, where θ is the angle between them. Work — the {{c1::dot product}} of force and displacement — is the classic physics example.', cloze_count = 2 WHERE id = '95109394-fba6-46f2-93ba-03d4b7826c74';
UPDATE flashcards SET cloze_text = 'A {{c1::scalar}} is a physical quantity with {{c2::magnitude only}} — no direction. {{c1::Scalar}} examples include {{c3::distance, speed, mass, energy, pressure, and the coefficients of friction}}.', cloze_count = 3 WHERE id = '96aadd80-438b-47aa-9326-324694289b47';
UPDATE flashcards SET cloze_text = '{{c1::Displacement}} is the vector from a starting point to an ending point — fully determined by those two locations alone, regardless of the path actually taken. {{c2::Distance}} is a scalar reflecting the total path length and is always ≥ |{{c1::displacement}}|.', cloze_count = 2 WHERE id = '9909d728-ead5-49f4-bc6e-fdd506e8b64a';
UPDATE flashcards SET cloze_text = 'On a velocity-vs-time graph, the {{c1::slope}} at any instant gives the acceleration. A positive {{c1::slope}} means acceleration parallel to velocity (speeding up); a negative {{c1::slope}} means acceleration antiparallel to velocity (slowing down or reversing direction).', cloze_count = 1 WHERE id = 'ab6f01ef-dd7d-4714-8bbb-1ccf7d21b82b';
UPDATE flashcards SET cloze_text = 'A {{c1::vector}} is a physical quantity with both {{c2::magnitude}} and {{c2::direction}}; common {{c1::vector}} examples include {{c3::displacement, velocity, acceleration, and force}}.', cloze_count = 3 WHERE id = 'be67e3d9-ae08-4a2f-952c-7f36f731f35a';
UPDATE flashcards SET cloze_text = '{{c1::Velocity}} is a vector measuring the rate of change of {{c2::displacement}} with respect to time; its SI unit is {{c3::meters per second (m/s)}}, and its direction matches the direction of the {{c2::displacement}}.', cloze_count = 3 WHERE id = 'cfd2c762-11ec-479f-95f1-681ca1f9089b';
UPDATE flashcards SET cloze_text = '{{c1::Mass}} quantifies an object''s {{c2::inertia}} — its resistance to acceleration — and is a {{c3::scalar}} with SI unit the {{c4::kilogram}}. {{c1::Mass}} is independent of location. {{c5::Weight}}, by contrast, is the gravitational force on that {{c1::mass}}; it is a {{c3::vector}} measured in {{c6::newtons}}.', cloze_count = 6 WHERE id = 'e419b73a-f19b-42ff-b015-bb1f7cc2fd42';
UPDATE flashcards SET cloze_text = 'For an object moving along a circular path, the instantaneous velocity vector is always {{c1::tangent}} to the circle at the object''s current position — perpendicular to the radius at that point. If the centripetal force were suddenly removed, the object would continue in a straight line along this {{c1::tangent}}.', cloze_count = 1 WHERE id = 'e61c4404-7425-4ffa-86be-7d9cd3df6797';
UPDATE flashcards SET cloze_text = 'In Newtonian physics, {{c1::mass}} is the measure of an object''s {{c2::inertia}} — its resistance to a change in velocity. The greater the {{c1::mass}}, the larger the force required to produce a given acceleration.', cloze_count = 2 WHERE id = 'eae0bc71-9b47-4a12-beaf-b9cd55bd1af7';
UPDATE flashcards SET cloze_text = '{{c1::Speed}} is a scalar — the magnitude of velocity for instantaneous values, but the ratio of {{c2::distance traveled to elapsed time}} for averages. Average {{c1::speed}} and the magnitude of average velocity are NOT generally equal, because distance ≥ |displacement|.', cloze_count = 2 WHERE id = 'f54048c2-7e59-4079-9d93-5777389aff8c';
UPDATE flashcards SET cloze_text = '{{c1::Base units}} are the seven foundational SI units (meter, kilogram, second, etc.) from which every other unit is built. {{c2::Derived units}} are constructed by combining {{c1::base units}} — for example, m/s for velocity, m/s² for acceleration, and kg·m/s² (the newton) for force.', cloze_count = 2 WHERE id = 'fa4d8c3e-fcda-4971-8044-ff56c4fccb63';
-- ── Naming Organic Molecules ──
UPDATE flashcards SET cloze_text = 'In an {{c1::ester}}, the hydroxyl (-OH) of a carboxylic acid is replaced by an alkoxy group (-OR). These compounds are named in two parts: the {{c2::alkyl group}} from the alcohol comes first, and the acid name has its {{c3::-oic acid}} suffix replaced by {{c3::-oate}} (e.g., ethyl ethanoate, common name ethyl acetate).', cloze_count = 3 WHERE id = '01cbd85e-daf4-422c-9f76-0b9f08cdf15f';
UPDATE flashcards SET cloze_text = 'The underlying logic of functional group priority is {{c1::oxidation state}}: the more bonds a carbon has to heteroatoms (O, N, halogens), the {{c2::higher}} its {{c1::oxidation state}} and the {{c2::higher}} its IUPAC priority; bonds to hydrogen lower the {{c1::oxidation state}}.', cloze_count = 2 WHERE id = '0fbc876a-0b35-44eb-a9f5-180c6ab9cd43';
UPDATE flashcards SET cloze_text = 'In a molecule with both an {{c1::alcohol}} and a multiple bond (alkene or alkyne), the {{c1::alcohol takes priority}} for naming — because the hydroxyl-bearing carbon is more highly oxidized than the doubly- or triply-bonded carbons.', cloze_count = 1 WHERE id = '25706b6d-25ef-4736-9b54-53bbab0c7c6b';
UPDATE flashcards SET cloze_text = 'An {{c1::anhydride}} forms when two carboxylic acid molecules condense and a water molecule is removed; if both acids are the same, the {{c1::anhydride}} is named by replacing "acid" with {{c2::"anhydride"}} in the parent name (e.g., acetic {{c2::anhydride}} from two acetic acids).', cloze_count = 2 WHERE id = '4c469b8b-783b-48ae-8f82-e0f0721c283d';
UPDATE flashcards SET cloze_text = 'Carbon atoms in the parent chain are numbered so that the {{c1::highest-priority functional group}} receives the {{c2::lowest possible locant}}; when priority is uniform, the numbering minimizes the {{c2::locants}} of the substituents.', cloze_count = 2 WHERE id = '4eec8157-d9af-49bd-8dd4-d0d54ca14f85';
UPDATE flashcards SET cloze_text = 'In an {{c1::amide}}, the hydroxyl (-OH) of a carboxylic acid is replaced by an {{c2::amino group}} (-NH₂, -NHR, or -NR₂). {{c1::Amides}} are named by replacing the parent acid''s {{c3::-oic acid}} suffix with {{c3::-amide}}.', cloze_count = 3 WHERE id = '78bfe7f4-a88e-4562-8e3d-f286e285a178';
UPDATE flashcards SET cloze_text = 'When a molecule contains both an {{c1::aldehyde}} and a ketone, the {{c1::aldehyde}} takes priority for the suffix (because it is terminal and more oxidized at its carbon); the ketone is then named as an {{c2::oxo-}} substituent on the same parent chain.', cloze_count = 2 WHERE id = '921f8706-6893-433e-9e39-8998b4ed4adb';
UPDATE flashcards SET cloze_text = 'When a chain contains both a {{c1::double}} and a triple bond and they would receive the same set of locants from either direction, numbering gives the {{c1::double bond}} the lower locant — the convention is "{{c1::double}} over triple" when their priorities tie.', cloze_count = 1 WHERE id = 'c9d05eb1-2961-4872-81ea-d96b1725940c';
UPDATE flashcards SET cloze_text = '{{c1::Aldehydes}} have a carbonyl (C=O) group at the {{c2::end of the carbon chain}} and are named by replacing the parent alkane''s -e with {{c3::-al}}. Because {{c1::aldehydes}} are terminal, the carbonyl carbon is always {{c4::carbon number 1}}.', cloze_count = 4 WHERE id = 'cce4d0d2-626b-41c4-b465-3e45fd35319a';
UPDATE flashcards SET cloze_text = 'If an {{c1::asymmetric anhydride}} is formed from two different carboxylic acids, both acids are named in alphabetical order before the word "anhydride" — e.g., ethanoic propanoic anhydride for the anhydride derived from acetic and propionic acids.', cloze_count = 1 WHERE id = 'dc55baad-92c5-48b6-954e-871823f14a69';
UPDATE flashcards SET cloze_text = 'Diols with both hydroxyl groups on the {{c1::same carbon}} are called {{c2::geminal diols}}; diols with hydroxyl groups on {{c3::adjacent carbons}} are called {{c4::vicinal diols}}. {{c2::Geminal diols}} are unstable and spontaneously {{c5::dehydrate}} to form a carbonyl compound (C=O).', cloze_count = 5 WHERE id = 'e1388a68-3e7a-45c2-9ea5-8eab42b29d19';
UPDATE flashcards SET cloze_text = 'Every IUPAC name follows the pattern {{c1::prefix}} – {{c2::parent chain}} – {{c3::suffix}}: the {{c1::prefix}} lists the substituents (in alphabetical order with locants), the {{c2::parent chain}} names the longest carbon chain, and the {{c3::suffix}} encodes the highest-priority functional group.', cloze_count = 3 WHERE id = 'f5dc5e93-95c6-43a7-a935-1a886b51a3f0';
-- ── Nitrogen and Phosphorus Containing Compounds ──
UPDATE flashcards SET cloze_text = 'The α-carbon between the two ester {{c2::carbonyl}}s of phthalimidomalonic ester is acidic (pKa ≈ {{c1::13}}) because the resulting enolate is stabilized by both adjacent {{c2::carbonyl}} groups.', cloze_count = 2 WHERE id = '39f4f76d-f447-41b0-8eb2-49f21aff1f78';
UPDATE flashcards SET cloze_text = 'In a strongly acidic solution, both the carboxyl and amino groups are fully {{c1::protonated}}, giving the amino acid a net {{c1::positive}} charge.', cloze_count = 1 WHERE id = '48188be8-8b6f-43c7-9f4e-cb36452b4d86';
UPDATE flashcards SET cloze_text = 'The {{c1::basic (positively charged)}} amino acids are {{c2::lysine (Lys/K)}}, {{c2::arginine (Arg/R)}}, and {{c2::histidine (His/H)}}; their side chains carry a positive charge at physiological pH ({{c2::histidine}} is partially).', cloze_count = 2 WHERE id = '4e3a3419-d862-4bab-8e3f-a2ef169d91b4';
UPDATE flashcards SET cloze_text = 'A {{c1::phosphodiester bond}} forms when a single phosphate group is esterified to TWO separate hydroxyl groups; {{c1::phosphodiester bonds}} link the {{c2::sugar}} backbones of DNA and RNA.', cloze_count = 2 WHERE id = '8e821bd2-cc4a-4f73-9e35-8d9cd8f2cc47';
UPDATE flashcards SET cloze_text = 'A {{c1::polypeptide}} is a chain of amino acids linked by peptide bonds; {{c1::polypeptides}} are the basic building blocks of proteins, which are large, folded {{c1::polypeptides}} with functional roles.', cloze_count = 1 WHERE id = 'a7295199-867c-4d2e-a82b-5da9c4f8de11';
-- ── Nonenzymatic Protein Function and Protein Analysis ──
UPDATE flashcards SET cloze_text = '{{c1::Voltage-gated}} channels open or close in response to changes in {{c2::membrane potential}}; {{c1::voltage-gated}} Na⁺ channels drive the depolarization phase of the action potential.', cloze_count = 2 WHERE id = '17a24364-3092-4567-a643-79c9bf2557c0';
UPDATE flashcards SET cloze_text = '{{c1::Actin}} monomers polymerize into microfilaments and form the thin filaments of muscle myofibrils; {{c1::actin}} is the most {{c2::abundant}} protein in eukaryotic cells.', cloze_count = 2 WHERE id = '1e467ade-4bca-4050-85a0-35ca51097bf5';
UPDATE flashcards SET cloze_text = '{{c1::G protein-coupled receptors (GPCRs)}} are the largest class of membrane receptors in humans; ligand binding activates a {{c2::heterotrimeric}} {{c1::G protein}} that then alters intracellular signaling.', cloze_count = 2 WHERE id = '2612eff9-764b-418f-96c3-5f0004b5ecc5';
UPDATE flashcards SET cloze_text = '{{c1::Complement activation}}: bound antibodies recruit {{c1::complement}} proteins, which assemble into pores that lyse the pathogen directly.', cloze_count = 1 WHERE id = '3378aabf-b3dc-42f5-8a97-1bd589027509';
UPDATE flashcards SET cloze_text = '{{c1::Ungated (leak) channels}} are always open and let ions flow freely down their gradient; the {{c2::potassium}} {{c1::leak}} channel is the main contributor to the resting membrane potential.', cloze_count = 2 WHERE id = '5f6b78c1-d20d-4c4f-b2a6-9e0e4596aa8b';
UPDATE flashcards SET cloze_text = 'In {{c1::ion-exchange}} chromatography, the column beads carry a {{c2::charge}}; proteins with the opposite {{c2::charge}} bind tightly and are retained, while proteins of the same sign flow through quickly.', cloze_count = 2 WHERE id = '6d325551-dca8-41fd-b174-e85b8e9cbc6a';
UPDATE flashcards SET cloze_text = '{{c1::Retention time}} is how long a compound spends bound to the stationary phase. Components with high affinity for the stationary phase have long {{c1::retention times}}; components that prefer the mobile phase {{c2::elute}} faster.', cloze_count = 2 WHERE id = '8f6ab7e0-5e66-4db9-840c-95fc3b68d4bd';
UPDATE flashcards SET cloze_text = '{{c1::Gs}} stimulates {{c2::adenylyl cyclase}}, raising intracellular cAMP. {{c3::Gi}} inhibits {{c2::adenylyl cyclase}}, lowering intracellular cAMP.', cloze_count = 3 WHERE id = 'c1166522-1c01-44d7-b165-207b2f6e96d2';
UPDATE flashcards SET cloze_text = '{{c1::Ligand-gated}} channels open when a specific chemical messenger binds; for example, the nicotinic {{c2::acetylcholine}} receptor on muscle opens to admit Na⁺ when {{c2::ACh}} binds.', cloze_count = 2 WHERE id = 'e37beb5a-6612-49ce-bb29-a4a7be883718';
UPDATE flashcards SET cloze_text = 'In {{c1::column chromatography}}, the stationary phase is a {{c1::column}} packed with polar beads (silica or alumina); the less polar a compound, the {{c2::faster}} it elutes.', cloze_count = 2 WHERE id = 'f0fd9120-0d7c-4760-8430-c6dbf23a9128';
-- ── Oxidation-Reduction Reactions ──
UPDATE flashcards SET cloze_text = 'Half-reaction balancing steps: balance non-H/O atoms, balance O with {{c1::H₂O}}, balance H with {{c2::H⁺}}, balance charge with {{c3::electrons (e⁻)}}, then scale and add so the {{c3::electrons}} cancel.', cloze_count = 3 WHERE id = '4fc9e9dc-c998-4cb7-a6fc-f7d31d476f5c';
UPDATE flashcards SET cloze_text = 'An {{c1::oxidizing agent}} causes another species to be {{c2::oxidized}} and is itself {{c2::reduced}}; a {{c1::reducing agent}} causes another species to be {{c2::reduced}} and is itself {{c2::oxidized}}.', cloze_count = 2 WHERE id = '90591256-6892-4191-ab98-3a1732d252b3';
-- ── Periodic Trends & Chemical Families ──
UPDATE flashcards SET cloze_text = 'The {{c1::periodic law}} states that the chemical and physical properties of the elements are a {{c1::periodic}} function of their {{c2::atomic numbers}} — as Z increases, certain properties recur at regular intervals corresponding to the underlying electronic structure.', cloze_count = 2 WHERE id = '00bd9c05-b7e9-4d9a-9921-10f387db7ee6';
UPDATE flashcards SET cloze_text = 'For any A-group representative element, the Roman numeral above the group equals the {{c1::number of valence electrons}} — e.g., Group 5A elements have 5 {{c1::valence electrons}}, Group 7A have 7.', cloze_count = 1 WHERE id = '223a70eb-00cc-48ad-8824-124d1aec061a';
UPDATE flashcards SET cloze_text = 'The {{c1::lanthanide and actinide series}} make up the two rows usually shown beneath the main periodic table; they constitute the {{c2::f-block}}, with valence electrons occupying the highest {{c3::s and f subshells}}. The {{c1::actinides}} include all of the synthetic transuranium elements (Z > 92).', cloze_count = 3 WHERE id = '51c5de5b-d7e0-4d3b-b69e-c6d8f8ea5fb5';
UPDATE flashcards SET cloze_text = 'Metals conduct heat and electricity well because their valence electrons are {{c1::loosely held and delocalized}} — free to move through the metallic lattice. The same {{c1::delocalized}} electron "sea" is responsible for the metallic {{c2::luster}}, since {{c1::loose}} electrons readily absorb and re-emit visible light.', cloze_count = 2 WHERE id = '535e2355-5d26-4e83-a122-be2c2a44be1f';
UPDATE flashcards SET cloze_text = 'The {{c1::alkali metals}} ({{c1::Group 1A}}) possess most classic metallic properties but with notably {{c2::lower densities}} than other metals; they have the {{c3::largest atomic radii}} in their period and correspondingly the {{c4::lowest ionization energy, electron affinity, and electronegativity}} of any element in their period.', cloze_count = 4 WHERE id = '6a7030ef-e87b-4789-b0c5-86c428e9521a';
UPDATE flashcards SET cloze_text = '{{c1::Effective nuclear charge (Zeff)}} is the net positive charge actually experienced by an atom''s outermost electrons after accounting for {{c2::shielding}} by the inner-shell electrons — formally Zeff ≈ {{c3::Z − S}}, where S is the {{c2::shielding}} constant.', cloze_count = 3 WHERE id = '8c04acab-ca5b-4849-a165-5138bc535b4e';
UPDATE flashcards SET cloze_text = '{{c1::Ionization energy}} is the energy required to remove one electron from a gaseous atom or ion in its ground state; because pulling a negative electron away from a positive nucleus always requires input of energy, {{c1::ionization}} is an {{c2::endothermic}} process.', cloze_count = 2 WHERE id = '918d2a65-d854-4131-bcb0-20920648cefc';
UPDATE flashcards SET cloze_text = 'Horizontal rows of the periodic table are called {{c1::periods}}; every element to the right has one more proton (and one more electron) than the element to its left. Vertical columns are called {{c2::groups}} (or families); elements within a {{c2::group}} share the same {{c3::valence electron configuration}} and therefore similar chemistry.', cloze_count = 3 WHERE id = 'fbb48398-c8ec-4103-b02d-0225e91fb7c2';
-- ── Reasoning About Research Design ──
UPDATE flashcards SET cloze_text = 'In a {{c1::single-blind}} trial, only one party is unaware of group assignment; in a {{c1::double-blind}} trial, the {{c2::subject, investigator, and assessor}} are all unaware.', cloze_count = 2 WHERE id = '158b3211-fc85-4bc1-82a8-68478a8a7465';
UPDATE flashcards SET cloze_text = '{{c1::Autonomy}} (respect for {{c1::autonomy}}) is the duty to respect the patient''s {{c2::own decisions about their own health care}}.', cloze_count = 2 WHERE id = '3fc5c06b-4954-4f00-99f2-036c61482d1d';
UPDATE flashcards SET cloze_text = 'Hill''s {{c1::dose-response}} criterion — as the exposure increases, the response should {{c2::increase proportionally}}; a consistent {{c1::dose-response}} relationship strengthens the causal inference.', cloze_count = 2 WHERE id = '80d64a04-c63c-4520-a0ea-0282e86e412e';
UPDATE flashcards SET cloze_text = '{{c1::Justice}} is the duty to distribute health-care resources {{c2::fairly}} and to treat {{c3::similar}} patients with {{c3::similar care}} — it applies to both the choice of research topic and the execution of the study.', cloze_count = 3 WHERE id = '97906082-bead-4b8a-8143-7db614303e0f';
UPDATE flashcards SET cloze_text = 'A {{c1::parameter}} is a value calculated from a {{c2::population}}; a {{c1::statistic}} is a value calculated from a {{c2::sample}} and is used to estimate the {{c1::parameter}}.', cloze_count = 2 WHERE id = '9d85c941-a924-441b-b1bd-0348fb0cd248';
UPDATE flashcards SET cloze_text = 'A {{c1::population}} is the complete group of all individuals who satisfy the attributes of interest; a {{c1::sample}} is any subset drawn from a {{c1::population}}.', cloze_count = 1 WHERE id = 'ff460f88-4793-4e67-a78a-db492fccce92';
-- ── Sensory Systems & Perception ──
UPDATE flashcards SET cloze_text = 'The {{c1::visual cortex}} (sometimes called the striate {{c1::cortex}}) is located in the {{c2::occipital lobe}}. It performs the deepest analysis of {{c1::visual}} information — edge detection, color processing, motion analysis, and object recognition — drawing on input streams that have already been filtered by the retina, LGN, and other relays.', cloze_count = 2 WHERE id = '0950a42a-f46e-4029-9602-53cf9cc729af';
UPDATE flashcards SET cloze_text = '{{c1::Perception}} is the higher-order processing of incoming sensory signals to extract their {{c2::meaning and significance}}. While sensation is performed by peripheral receptors, {{c1::perception}} is the work of the {{c3::central nervous system}}, integrating raw input with memory and context.', cloze_count = 3 WHERE id = '1ddb06f7-03cf-415c-855c-c776e03c960f';
UPDATE flashcards SET cloze_text = '{{c1::Interposition (occlusion)}} is the monocular cue that an object which partially covers another must be {{c2::closer}} than the object it is blocking. This is a very strong cue — {{c1::interposition}} almost never lies.', cloze_count = 2 WHERE id = '210d3f58-09e7-46f7-b674-cb3f9ee561ac';
UPDATE flashcards SET cloze_text = 'The {{c1::lens}} sits behind the iris and provides the variable focusing the cornea cannot. It is suspended by {{c2::suspensory ligaments}} attached to the {{c3::ciliary muscle}}; when the {{c3::ciliary muscle}} contracts (under parasympathetic control), it changes the {{c1::lens}}''s curvature to focus on near versus distant objects — a process called {{c4::accommodation}}.', cloze_count = 4 WHERE id = '22d67111-101b-46af-8b2f-5bc74c251240';
UPDATE flashcards SET cloze_text = '{{c1::Retinal disparity}} is the most important binocular depth cue: the {{c2::slight difference between the images projected onto the two retinas}}. Because the eyes are horizontally separated, each eye sees a scene from a marginally different angle, and the visual cortex computes depth from the {{c1::disparity}}. The {{c3::more disparate}} the two images, the {{c4::closer}} the object.', cloze_count = 4 WHERE id = '282e7404-76cf-4e6e-8051-10eab00d24b8';
UPDATE flashcards SET cloze_text = '{{c1::Feature detector cells}} respond selectively to a particular visual feature — a specific orientation of an edge, a specific direction of motion, or a specific contour shape. Higher cortical areas combine the outputs of many {{c1::feature detectors}} to recognize complex objects.', cloze_count = 1 WHERE id = '302c6825-fb79-42e4-8a26-d6deb301dc64';
UPDATE flashcards SET cloze_text = 'The {{c1::threshold of conscious perception}} is the higher intensity required for a stimulus to be consciously noticed. Stimuli that exceed the absolute threshold (and thus reach the CNS) but fall short of {{c1::conscious perception}} are called {{c2::subliminal}} — they are processed by the brain but never reach awareness.', cloze_count = 2 WHERE id = '3115a8ac-83cd-489c-a059-1a9299be08f3';
UPDATE flashcards SET cloze_text = '{{c1::Cones}} require bright light to function but support color vision and high-acuity discrimination of fine detail. There are three {{c1::cone}} types, each preferring a different wavelength range: {{c2::short (S, blue), medium (M, green), and long (L, red)}}; together their activation patterns let the brain distinguish thousands of colors.', cloze_count = 2 WHERE id = '31ef1d9f-7d8e-4274-b0fe-ddfbc4b3e5f7';
UPDATE flashcards SET cloze_text = 'Hair cells are named for the tuft of {{c1::stereocilia}} projecting from their surface. When the basilar membrane vibrates, the {{c1::stereocilia}} {{c2::sway against the tectorial membrane}}, opening {{c3::mechanically gated ion channels}}. The resulting ion flow depolarizes the hair cell and generates a receptor potential that is converted to action potentials in the auditory nerve.', cloze_count = 3 WHERE id = '46de06f4-c4c0-4e9c-a018-500ac9973ed7';
UPDATE flashcards SET cloze_text = '{{c1::Top-down (conceptually-driven)}} processing constructs perceptions starting from {{c2::memory and expectations}}, then fitting incoming sensory data into the predicted whole. It is {{c3::faster but more error-prone}} — perceptual illusions and misperceptions arise when the {{c2::expectations}} are wrong.', cloze_count = 3 WHERE id = '4a87a6db-f332-4617-9fd1-cdeca5f20426';
UPDATE flashcards SET cloze_text = '{{c1::Sensation}} is the process of {{c2::transduction}} — converting physical stimuli (light, sound, pressure, chemicals, and so on) from the environment into {{c3::electrical signals}} the nervous system can transmit. {{c1::Sensation}} happens at the sensory receptors of the peripheral nervous system.', cloze_count = 3 WHERE id = '4fd51756-b825-407a-bf89-b0e2875f2733';
UPDATE flashcards SET cloze_text = '{{c1::Sensory receptors}} are specialized neurons that respond to environmental stimuli by triggering electrical signals (action potentials) carried toward the central nervous system. Different {{c1::receptor}} classes respond selectively to different forms of energy.', cloze_count = 1 WHERE id = '5d61c113-d1a7-41b2-b5c4-ba91ff6c88c8';
UPDATE flashcards SET cloze_text = 'The Gestalt {{c1::law of good continuation}} states that elements arranged along a {{c2::smooth, continuous path}} tend to be perceived as a single unit. Two crossing lines are seen as two whole lines rather than four meeting segments because we perceive each line as passing straight through the intersection.', cloze_count = 2 WHERE id = '5f0881be-0bb9-49e5-a64a-501a5fd4d61a';
UPDATE flashcards SET cloze_text = '{{c1::Physiological zero}} is the normal temperature of the skin used as the brain''s reference for thermal perception. Objects warmer than {{c1::physiological zero}} are judged hot; objects cooler are judged cold — even though both may be at temperatures far from any absolute standard.', cloze_count = 1 WHERE id = '60542c14-39d4-4991-aee0-dfea7eee724d';
UPDATE flashcards SET cloze_text = 'Not all visual fibers go through the LGN. A side branch projects directly to the {{c1::superior colliculus}} in the midbrain, which mediates {{c2::reflexive eye movements}} and rapid orientations to visual stimuli — for example, turning your head toward sudden movement in your periphery.', cloze_count = 2 WHERE id = '66efbe62-7523-4f03-b1db-99fe40e99ad5';
UPDATE flashcards SET cloze_text = 'The Gestalt {{c1::law of proximity}} states that visual elements located {{c2::close together}} in space tend to be perceived as belonging to a single {{c3::group}}. Spatial nearness is a powerful organizing cue — even when the grouped elements are dissimilar in shape or color, {{c1::proximity}} is often sufficient to bind them perceptually.', cloze_count = 3 WHERE id = '68e1956b-9577-4391-8f51-415e5e33b534';
UPDATE flashcards SET cloze_text = 'A {{c1::sensory threshold}} is the minimum stimulus required to produce some perceptual outcome. Different {{c1::thresholds}} describe different perceptual transitions — from detection, to conscious awareness, to discrimination between two stimuli.', cloze_count = 1 WHERE id = '69646046-6610-49bf-9295-fa184f2a2e60';
UPDATE flashcards SET cloze_text = 'The {{c1::absolute threshold}} is the {{c2::minimum stimulus intensity}} required to activate a sensory system. Below the {{c1::absolute threshold}}, the stimulus is not transduced into action potentials and never reaches the CNS at all.', cloze_count = 2 WHERE id = '6b9d26dc-6b18-4f7e-9fcf-7e1426a12685';
UPDATE flashcards SET cloze_text = 'The {{c1::cochlea}} is a spiral-shaped organ in the inner ear that contains the receptors for {{c2::hearing}}. Its interior is divided into three parallel chambers called {{c3::scalae}}; the middle scala houses the actual {{c2::hearing}} apparatus, the organ of Corti.', cloze_count = 3 WHERE id = '8442b8e0-b140-4627-b2d9-1f72bebb6961';
UPDATE flashcards SET cloze_text = 'The middle ear contains the three smallest bones in the body — the {{c1::malleus, incus, and }}{{c2::stapes}}{{c1:: (sometimes called hammer, anvil, and }}{{c2::stirrup}}{{c1::)}}. They amplify the vibrations from the tympanic membrane and transmit them to the inner ear; the base of the {{c2::stapes}} rests on the {{c3::oval window}} of the cochlea.', cloze_count = 3 WHERE id = '88a45af1-92c4-4200-b7d7-30b91ebd9106';
UPDATE flashcards SET cloze_text = 'The {{c1::utricle and saccule}} sit in the vestibule and detect {{c2::linear acceleration}} (and the static pull of gravity). Each contains modified hair cells capped with calcium-carbonate crystals called {{c3::otoliths}}. As the head accelerates, the {{c3::otoliths}} lag behind by inertia, bending the hair cells and signaling motion.', cloze_count = 3 WHERE id = '9b5eb629-a80b-48ef-b469-aa35db179f78';
UPDATE flashcards SET cloze_text = 'The {{c1::difference threshold}} — also called the {{c1::just noticeable difference (JND)}} — is the smallest magnitude difference between two stimuli that an observer can reliably detect. {{c2::Weber''s law}} generalizes the finding: the {{c1::JND}} is a {{c3::constant proportion}} of the original stimulus magnitude (not a fixed absolute amount) across most of the perceptible range.', cloze_count = 3 WHERE id = '9ee7c3cb-24d9-4f1b-90f9-789aacfdff74';
UPDATE flashcards SET cloze_text = 'The outer ear consists of the visible {{c1::pinna (auricle)}}, which channels sound waves into the {{c2::external auditory canal}}, which directs them to the {{c3::tympanic membrane (eardrum)}}. The {{c3::tympanic membrane}} separates the outer ear from the middle ear.', cloze_count = 3 WHERE id = 'a188d761-3532-4cac-8794-155cd67aa540';
UPDATE flashcards SET cloze_text = '{{c1::Place theory}} states that the {{c2::location}} of a vibrating hair cell along the basilar membrane determines the perceived {{c3::pitch}} of a sound. Each {{c2::location}} is mechanically tuned to a different frequency, so which hair cells fire encodes the frequency content of the sound.', cloze_count = 3 WHERE id = 'a3d94828-0453-4e4c-a851-0922af112276';
UPDATE flashcards SET cloze_text = 'The Gestalt {{c1::law of similarity}} states that visual elements sharing some property (color, shape, size) tend to be {{c2::grouped together}}, even when they are spatially separated. Color and shape {{c1::similarity}} can override proximity to organize elements into perceptual groups.', cloze_count = 2 WHERE id = 'bac8e69b-58a6-442b-b9ba-e6fe9363d74d';
UPDATE flashcards SET cloze_text = 'The {{c1::macula}} is a small central region of the retina densely packed with {{c3::cones}}. At its center sits the {{c2::fovea}} — containing exclusively {{c3::cones}}, no rods — which provides the sharpest visual acuity in normal daylight viewing. When you look directly at something, you are projecting it onto the {{c2::fovea}}.', cloze_count = 3 WHERE id = 'bc14f848-1fdc-4f55-a359-24e6b0a43a51';
UPDATE flashcards SET cloze_text = '{{c1::Relative size}} is the monocular depth cue that {{c2::larger}} retinal images come from {{c3::closer}} objects, assuming similar real-world size. If you know two objects are roughly the same actual size, the one that projects a {{c2::larger}} image must be {{c3::closer}}.', cloze_count = 3 WHERE id = 'caad0bb9-2630-46d6-9877-e259ee87f8f5';
UPDATE flashcards SET cloze_text = 'The {{c1::two-point threshold}} is the minimum distance between two points of skin contact such that they can be felt as {{c2::two distinct stimuli}} rather than one. The threshold varies enormously across the body — fingertips have very small {{c1::two-point thresholds}} (high acuity), while the back has very large ones.', cloze_count = 2 WHERE id = 'cb1cb81f-e216-4041-8bd9-116dfdac26a8';
UPDATE flashcards SET cloze_text = 'The three {{c1::semicircular canals}} detect {{c2::rotational acceleration}} in three perpendicular planes (one for each canal). Each canal ends in a swelling called an {{c3::ampulla}} containing hair cells. When the head rotates, endolymph in the canal lags behind by inertia, bending the hair cells in the {{c3::ampulla}}.', cloze_count = 3 WHERE id = 'cc47d209-88f6-4433-8f07-345d75999432';
UPDATE flashcards SET cloze_text = 'Smell is detected by {{c1::olfactory chemoreceptors}} embedded in the {{c2::olfactory epithelium}} at the top of the nasal cavity. Volatile compounds inhaled into the nasal passages must {{c3::bind}} their matching {{c1::chemoreceptors}} to trigger a signal.', cloze_count = 3 WHERE id = 'd8d0194a-5926-4830-a31a-0ecfc4a93568';
UPDATE flashcards SET cloze_text = '{{c1::Sensory adaptation}} is the gradual reduction in receptor or perceptual response to a {{c2::constant stimulus}} over time — the reason you stop noticing the smell of your own house, the touch of your clothing, or background noise. {{c1::Adaptation}} has both peripheral (receptor-level) and central (perceptual) components.', cloze_count = 2 WHERE id = 'e39c7a8b-1d6c-4b77-8c55-59224a8d2c9f';
UPDATE flashcards SET cloze_text = 'Light first passes through the {{c1::cornea}}, a clear dome at the front of the eye that gathers and pre-focuses the incoming rays. The {{c2::iris}} is the colored ring of muscle behind it; the {{c2::iris}} contains a {{c3::dilator pupillae}} (sympathetic) that widens the pupil and a {{c3::constrictor pupillae}} (parasympathetic) that narrows it.', cloze_count = 3 WHERE id = 'e685b04d-2e3c-49b9-9f3a-80b081f3aa4c';
UPDATE flashcards SET cloze_text = '{{c1::Convergence}} is the second binocular depth cue: the brain detects {{c2::how much the two eyes turn inward}} to focus on an object. Greater {{c1::convergence}} means a closer object. The cue is effective at short distances but loses precision beyond a few meters, where the eyes are nearly parallel.', cloze_count = 2 WHERE id = 'ec963441-e7cd-4728-84f7-4367535ad803';
UPDATE flashcards SET cloze_text = 'A {{c1::sensory stimulus}} activates a {{c1::sensory}} receptor and initiates sensation. An {{c2::incentive stimulus}} is an external object or event that motivates behavior by offering a reward or punishment — its role is motivational rather than purely perceptual.', cloze_count = 2 WHERE id = 'f1cdbc4b-aef8-4255-a71f-f549ebfd0f34';
UPDATE flashcards SET cloze_text = 'The inner ear consists of a {{c1::bony labyrinth}} (a hollow cavity within the temporal bone) housing a continuous tubular {{c2::membranous labyrinth}} suspended inside it. The {{c1::bony labyrinth}} is filled with {{c3::perilymph}}; the {{c2::membranous labyrinth}} is filled with potassium-rich {{c4::endolymph}}.', cloze_count = 4 WHERE id = 'f3b3daef-1fc2-4376-b417-a8f1442da090';
UPDATE flashcards SET cloze_text = 'Cell bodies of sensory neurons outside the CNS cluster together in {{c1::sensory ganglia}}. The brain regions that ultimately analyze incoming sensory information are called {{c2::projection areas}} — for example, the visual cortex is the {{c2::projection area}} for visual input.', cloze_count = 2 WHERE id = 'f7626031-cbda-4b80-8576-1effb5f089e8';
-- ── Separations and Purifications ──
UPDATE flashcards SET cloze_text = '{{c1::Column chromatography}} packs the stationary phase ({{c2::silica or alumina beads}}) into a vertical tube and can separate by {{c3::polarity, size, or affinity}} depending on the {{c1::column}} type.', cloze_count = 3 WHERE id = '1e3f7a9d-769e-4f26-8843-85df85e6069f';
UPDATE flashcards SET cloze_text = '{{c1::Distillation}} separates liquids by differences in {{c2::boiling point}} — the component with the {{c3::lowest}} {{c2::boiling point}} vaporizes first and is collected after {{c4::condensing back to liquid}}.', cloze_count = 4 WHERE id = 'd7ecc137-f5de-41a5-86b0-68b91820e53a';
-- ── Social Stratification ──
UPDATE flashcards SET cloze_text = '{{c1::Social epidemiology}} studies how {{c2::social structures, institutions, and relationships}} shape health and disease distribution — for example, how SES inequality drives mortality differences.', cloze_count = 2 WHERE id = '2f682f5c-881f-4eb5-aa03-2eb842177464';
UPDATE flashcards SET cloze_text = '{{c1::Environmental justice}} is the {{c2::fair treatment and meaningful involvement}} of all people in {{c1::environmental}} decision-making, regardless of {{c3::race, color, national origin, or income}}.', cloze_count = 3 WHERE id = '9146c3bd-1863-4f3d-a13f-6b9dd7eee468';
UPDATE flashcards SET cloze_text = 'The {{c1::sick role (Parsons)}} legitimizes illness as socially acceptable deviance, exempting the ill from normal roles; the {{c2::illness experience}} (symbolic interactionist) is how people {{c3::incorporate illness into their self-identity}}.', cloze_count = 3 WHERE id = 'b3e778ab-faa9-45f6-853d-d73ac552789a';
UPDATE flashcards SET cloze_text = '{{c1::False consciousness}} — workers'' {{c2::misperception of their actual position}} within society''s class structure, often adopting the {{c3::ideology of the ruling class}} instead of recognizing their own oppression.', cloze_count = 3 WHERE id = 'b61d069b-9c58-45a2-8a91-a9ab8a157f8f';
UPDATE flashcards SET cloze_text = '{{c1::Spatial inequality}} is the {{c2::unequal distribution of resources across territories}} (neighborhoods, regions); {{c3::residential segregation}} is the voluntary or forced separation of cultural, ethnic, or racial groups into different {{c3::residential}} areas.', cloze_count = 3 WHERE id = 'bb4ba147-cf58-4f25-aca6-23f983fa78f5';
UPDATE flashcards SET cloze_text = 'Racial health disparities in the U.S.: {{c1::African Americans}} tend to have the {{c2::worst health profiles}}; {{c1::Asian Americans and Pacific Islanders}} tend to have the {{c2::best}}; racial and ethnic minorities overall experience poorer outcomes than white populations.', cloze_count = 2 WHERE id = 'eabe392c-a4ff-4dbe-a453-ff1f006ae580';
-- ── Social Structure and Demographics ──
UPDATE flashcards SET cloze_text = '{{c1::Teacher expectancy}} — {{c1::teachers}} tend to {{c2::get the performance they expect}} from students, which can become a self-fulfilling prophecy that reinforces social stratification.', cloze_count = 2 WHERE id = '7a5bce32-7f0e-4557-a107-80cb4801d209';
UPDATE flashcards SET cloze_text = 'Social movements are {{c1::proactive}} when they promote social change and {{c1::reactive}} when they resist it; {{c2::relative deprivation}} — feeling worse off compared to others or to one''s own past — often drives them.', cloze_count = 2 WHERE id = 'a1fa73fb-c538-4e76-845f-c895e953e732';
UPDATE flashcards SET cloze_text = 'Three related concepts: {{c1::gender inequality}} (intentional or unintentional empowerment of one gender over another), {{c1::gender stratification}} (uneven access to resources based on gender), and {{c1::gender segregation}} (separation of individuals by perceived gender).', cloze_count = 1 WHERE id = 'd7fff60a-fad2-4bb8-9545-d3ba0e70b2bc';
UPDATE flashcards SET cloze_text = 'The four principles of medical ethics: {{c1::beneficence}}, {{c1::nonmaleficence}}, {{c1::autonomy}}, and {{c1::justice}}.', cloze_count = 1 WHERE id = 'fb079a3c-2e97-4632-97d7-17be35b208a9';
-- ── Spectroscopy ──
UPDATE flashcards SET cloze_text = '{{c1::Infrared (IR) spectroscopy}} measures the absorption of light, which excites bonds into higher {{c2::vibrational}} states; it is primarily used to identify the {{c3::functional groups}} present in a molecule.', cloze_count = 3 WHERE id = 'a363aef1-db6f-4fb4-9953-f836227e2398';
UPDATE flashcards SET cloze_text = '{{c1::Transmittance}} is the fraction of incident IR light that passes through the sample to the detector; an absorption peak appears as a {{c2::dip}} in {{c1::transmittance}}.', cloze_count = 2 WHERE id = 'b39d3249-855e-4cd6-8e09-f456c09472e7';
UPDATE flashcards SET cloze_text = 'A UV-Vis spectrum is plotted as {{c1::absorbance}} on the y-axis vs {{c2::wavelength (nm)}} on the x-axis; the λ_max is the {{c2::wavelength}} at which the molecule absorbs most strongly.', cloze_count = 2 WHERE id = 'c5f487be-699c-4bb4-a065-efd79f5bd7ca';
UPDATE flashcards SET cloze_text = 'Increased {{c1::conjugation}} ({{c2::longer}} chains of alternating single and double bonds) lowers the HOMO-LUMO energy gap, pushing λ_max toward {{c2::longer}} wavelengths (red shift).', cloze_count = 2 WHERE id = 'cf564d47-c93e-4eec-8b9c-5c48ba0ef59b';
-- ── The Cell ──
UPDATE flashcards SET cloze_text = 'In {{c1::conjugation}}, a donor (F⁺) bacterium extends a {{c2::sex pilus}} to make physical contact with a recipient (F⁻) cell, then transfers DNA unidirectionally through the resulting {{c1::conjugation}} bridge.', cloze_count = 2 WHERE id = '183af75a-ce92-4924-b653-95372a996b3a';
UPDATE flashcards SET cloze_text = '{{c1::Archaea}} resemble {{c2::Bacteria}} morphologically — single circular chromosome, no nucleus, divide by binary fission — but resemble {{c2::Eukarya}} biochemically: their DNA associates with histones, their RNA polymerases are similar, and they initiate translation with unmodified methionine rather than the formylmethionine used by {{c2::Bacteria}}.', cloze_count = 2 WHERE id = '5b13d1b2-534d-40ce-8894-9b18c9d16514';
UPDATE flashcards SET cloze_text = 'A virus can only infect cell types that display the {{c1::specific surface receptors}} its attachment proteins recognize — which is why viral tropism (the range of cells a virus can enter) is so narrow and why their absence renders a cell effectively invisible to the virus.', cloze_count = 1 WHERE id = '5c1a379d-de9c-4781-9ffb-dca495627437';
UPDATE flashcards SET cloze_text = 'The dark, dense sub-region of the nucleus where {{c2::ribosomal RNA}} is transcribed and pre-assembled into {{c2::ribosomal}} subunits is the {{c1::nucleolus}}.', cloze_count = 2 WHERE id = '75b2adb6-7c88-465b-b4d2-89e855cffcb2';
UPDATE flashcards SET cloze_text = 'In the {{c1::lytic}} cycle a phage hijacks host machinery, assembles new virions, and bursts the cell open to release them; in the {{c2::lysogenic}} cycle the phage instead integrates its genome into the host chromosome as a {{c2::prophage}} that replicates passively until environmental stress triggers a switch back to the {{c1::lytic}} cycle.', cloze_count = 2 WHERE id = '9439b80d-3267-4a5b-bcc1-210e7d6f60a0';
UPDATE flashcards SET cloze_text = 'The {{c1::F (fertility) factor}} is a plasmid encoding the sex pilus required for conjugation; cells carrying it are designated {{c2::F⁺}} (donors) and cells lacking it are {{c2::F⁻}} (recipients).', cloze_count = 2 WHERE id = 'a52f05dd-8bbd-4d75-818d-f0a27b6dca47';
UPDATE flashcards SET cloze_text = 'The defining cytological split between {{c1::prokaryotes}} and {{c1::eukaryotes}} is the absence (vs. presence) of a {{c2::membrane-bound nucleus}}; only {{c1::eukaryotes}} also wrap their organelles in their own membranes.', cloze_count = 2 WHERE id = 'a6c4c78d-c67c-42d0-87a0-0040ac456a1f';
-- ── The Endocrine System ──
UPDATE flashcards SET cloze_text = 'When blood calcium falls, the {{c1::parathyroid}} glands release {{c1::parathyroid hormone (PTH)}}, which {{c2::raises}} circulating calcium — directly opposing the thyroid hormone {{c3::calcitonin}}, its physiological antagonist that lowers calcium.', cloze_count = 3 WHERE id = '16f66da1-e4c4-4fd8-a756-ef804f0a5420';
UPDATE flashcards SET cloze_text = 'Dietary iodine deficiency blocks synthesis of T₃ and T₄, lowering basal metabolic rate — the classic cause of {{c1::hypothyroidism}}.', cloze_count = 1 WHERE id = '64ef519c-5afb-4a3d-9193-ca91a32c2fc1';
UPDATE flashcards SET cloze_text = 'Because the posterior pituitary holds only {{c3::axon}} terminals, it {{c1::synthesizes no hormones of its own}} — instead, {{c2::hypothalamic}} neurons build ADH and oxytocin, then ferry them down their {{c3::axons}} to be stored and released from those terminals.', cloze_count = 3 WHERE id = '8efa4f8f-6eb5-4e35-b1e4-116f17b20b6e';
UPDATE flashcards SET cloze_text = 'Along the HPA axis, the hypothalamus releases {{c1::CRH (corticotropin-releasing hormone)}}, which drives the anterior pituitary to secrete {{c2::ACTH (adrenocorticotropic hormone)}}; {{c2::ACTH}} then signals the adrenal cortex''s zona fasciculata to release the glucocorticoid {{c3::cortisol}}.', cloze_count = 3 WHERE id = '9567b8d8-2d9f-48cd-9d6f-c08706613b13';
UPDATE flashcards SET cloze_text = 'Unlike other anterior pituitary hormones, {{c1::prolactin}} is held under tonic inhibitory control: the hypothalamus continuously releases {{c2::dopamine}} ({{c1::prolactin}}-inhibiting hormone), which suppresses {{c1::prolactin}} secretion until that brake is lifted.', cloze_count = 2 WHERE id = 'a4e3e66d-8719-4d04-b311-0ef493ff467a';
UPDATE flashcards SET cloze_text = 'Because {{c1::T₃ and T₄}} drive mitochondria to burn more oxygen for ATP and accelerate the turnover — both {{c3::synthesis and breakdown}} — of proteins and fats, they push the {{c2::basal metabolic rate}} upward.', cloze_count = 3 WHERE id = 'b384c1d6-cfb0-4ead-ba36-9c16af824672';
UPDATE flashcards SET cloze_text = 'Under the control of {{c1::TSH}} from the anterior pituitary, the thyroid runs two separate programs: {{c2::T₃ and T₄}} drive up the basal metabolic rate, while {{c3::calcitonin}} pushes blood calcium down by throttling osteoclasts.', cloze_count = 3 WHERE id = 'd1ca5ce4-04c4-442c-be03-9e94ff0667b1';
UPDATE flashcards SET cloze_text = 'G-protein activation of {{c1::phospholipase C (PLC)}} yields the second messenger {{c2::IP₃}}, which triggers {{c3::Ca²⁺}} release from the smooth endoplasmic reticulum.', cloze_count = 3 WHERE id = 'd22801e3-4020-4e13-af59-b8c8c109c0e8';
UPDATE flashcards SET cloze_text = 'In the distal nephron, the mineralocorticoid {{c1::aldosterone}} defends blood pressure by driving reabsorption of {{c2::Na⁺}} (water follows), while the negative luminal electrochemical gradient this creates favors secretion of {{c3::K⁺ and H⁺}} into the forming urine.', cloze_count = 3 WHERE id = 'd8cc8f2e-7cb0-4b1b-a9e3-3df1c4b6d2fc';
UPDATE flashcards SET cloze_text = 'Once a steroid hormone reaches its intracellular receptor, the resulting complex behaves as a {{c1::transcription factor}}: docking onto a specific DNA sequence, it {{c2::up- or down-regulates (increases or decreases)}} {{c1::transcription}} of the target gene.', cloze_count = 2 WHERE id = 'da685aa3-1949-4644-9030-65d2e2b2cf78';
UPDATE flashcards SET cloze_text = 'During labor, oxytocin from the posterior pituitary runs a {{c1::positive}} feedback loop: {{c2::cervical stretch}} triggers more oxytocin release, and the added oxytocin {{c3::intensifies uterine contractions}} that amplify the loop still further — the cycle breaking only at birth.', cloze_count = 3 WHERE id = 'e5391e4a-0abd-420f-8d39-7fa674b17b79';
UPDATE flashcards SET cloze_text = 'Strip the carboxyl off a single {{c1::amino acid}} — usually {{c2::tyrosine}} — and you get an amine hormone; this small class covers the catecholamines {{c3::epinephrine and norepinephrine}} plus the thyroid hormones {{c4::T₃ and thyroxine (T₄)}}.', cloze_count = 4 WHERE id = 'edfa7cc1-9f26-4d77-9c61-5e38393a4af8';
-- ── The Musculoskeletal System ──
UPDATE flashcards SET cloze_text = '{{c1::Creatine phosphate}} is built up at rest by transferring a {{c1::phosphate}} group from ATP to {{c1::creatine}}; during exertion, the reaction reverses to rapidly regenerate {{c2::ATP}} from ADP.', cloze_count = 2 WHERE id = '1e348748-2b82-42bf-a451-e639c6e78758';
UPDATE flashcards SET cloze_text = 'A {{c1::motor unit}} is a single motor neuron together with all the muscle fibers it innervates; recruiting more {{c1::motor units}} produces stronger overall contraction.', cloze_count = 1 WHERE id = '2dcbdd6b-c8cd-4093-b628-252c855225f5';
UPDATE flashcards SET cloze_text = '{{c1::Red (slow-twitch)}} fibers are rich in {{c2::myoglobin}} and {{c2::mitochondria}}; they rely on {{c3::aerobic}} metabolism and dominate in muscles built for sustained, endurance activity.', cloze_count = 3 WHERE id = '3490ae2a-f8c1-49e9-a468-e9910b4871d7';
UPDATE flashcards SET cloze_text = 'Myofibrils are wrapped by the {{c1::sarcoplasmic reticulum}}, a modified endoplasmic network that stores high concentrations of {{c2::Ca²⁺}} for release during contraction.', cloze_count = 2 WHERE id = '51a04229-4b02-4cbd-a7a3-9672c34764ed';
UPDATE flashcards SET cloze_text = 'The {{c1::synovium}} lines the joint capsule and secretes {{c2::synovial fluid}} that lubricates joint movement; {{c3::articular cartilage}} caps the bone surfaces to cushion impact.', cloze_count = 3 WHERE id = '73cce098-09de-46ec-98d9-398177b31ee7';
UPDATE flashcards SET cloze_text = 'In the {{c1::sliding filament model}}, repeated cross-bridge cycling causes the thin filaments to move past the thick filaments, {{c2::shortening}} the sarcomere — but the filaments themselves do not change length.', cloze_count = 2 WHERE id = '915d2522-3186-45c5-9a59-2d5485605cfa';
UPDATE flashcards SET cloze_text = 'Each muscle fiber (myocyte) contains many {{c1::myofibrils}} aligned in parallel; each {{c1::myofibril}} is a chain of sarcomeres joined end-to-end.', cloze_count = 1 WHERE id = 'b2190ad2-123d-453d-a4d3-f62625928a91';
-- ── The Nervous System ──
UPDATE flashcards SET cloze_text = 'The {{c1::Na⁺/K⁺ ATPase}} pumps {{c2::3 Na⁺}} out of the cell for every {{c3::2 K⁺}} pumped in, restoring the ion gradients that the action potential partially dissipates.', cloze_count = 3 WHERE id = '14b2a51f-d2d5-4481-8cde-b4791261e991';
UPDATE flashcards SET cloze_text = '{{c1::Afferent}} neurons (also called {{c2::sensory}} neurons) carry signals from {{c2::sensory}} receptors toward the central nervous system.', cloze_count = 2 WHERE id = '194601de-5b4b-4076-829a-bd6de094a22d';
UPDATE flashcards SET cloze_text = 'As Na⁺ enters one segment of the axon, it depolarizes the {{c1::adjacent segment}} to threshold, opening its Na⁺ channels too. This domino effect carries the action potential along the axon.', cloze_count = 1 WHERE id = '19e1f890-8c1b-4198-a9c5-913974273457';
UPDATE flashcards SET cloze_text = 'Both sympathetic and parasympathetic {{c1::preganglionic}} neurons release {{c2::acetylcholine}}. Parasympathetic postganglionic neurons release {{c2::acetylcholine}}, while most sympathetic postganglionic neurons release {{c3::norepinephrine}}.', cloze_count = 3 WHERE id = '21f0ddb4-5bf4-463b-83e4-8b2faf04e439';
UPDATE flashcards SET cloze_text = 'During the {{c1::absolute refractory period}}, the neuron cannot fire another action potential regardless of stimulus strength because Na⁺ channels are {{c2::inactivated}}.', cloze_count = 2 WHERE id = '2b702183-c6d7-44ca-b89f-8d62be5d9b3a';
UPDATE flashcards SET cloze_text = 'Potassium is far more concentrated {{c1::inside}} the neuron (~140 mM) than outside (~4 mM), so the K⁺ gradient drives K⁺ to leak {{c2::outward}} through leak channels.', cloze_count = 2 WHERE id = '30b956f0-3d03-425f-b192-2bbfcc521a58';
UPDATE flashcards SET cloze_text = 'Because every {{c2::action potential}} has the same amplitude, a stronger stimulus is signaled by an increased {{c1::frequency}} of firing, not by a larger {{c2::action potential}}.', cloze_count = 2 WHERE id = '32b300ed-328b-4f8f-81c8-b1e9fc2f4dfa';
UPDATE flashcards SET cloze_text = 'The {{c1::central nervous system (CNS)}} consists of the brain and spinal cord; the {{c2::peripheral nervous system (PNS)}} is everything else — the nerves connecting the {{c1::CNS}} to the rest of the body.', cloze_count = 2 WHERE id = '8d4dee4a-c6f9-408b-8d37-88148b3ecdf9';
UPDATE flashcards SET cloze_text = 'At threshold, {{c1::voltage-gated Na⁺ channels}} snap open; Na⁺ rushes inward down its electrochemical gradient and rapidly {{c2::depolarizes}} the membrane toward +35 mV.', cloze_count = 2 WHERE id = 'a8cf862a-8101-4791-8e7e-6c319ab45b36';
UPDATE flashcards SET cloze_text = 'K⁺ efflux briefly overshoots the resting potential, leaving the membrane temporarily more negative than -70 mV — {{c1::hyperpolarization}}. The Na⁺/K⁺ ATPase then restores the resting state.', cloze_count = 1 WHERE id = 'b3bdbfff-86f1-4567-a6c8-addb107af1c1';
UPDATE flashcards SET cloze_text = 'A {{c1::neuron}} is a specialized cell that converts incoming {{c2::chemical}} signals into an electrical impulse and then back into a {{c2::chemical}} signal at the next cell.', cloze_count = 2 WHERE id = 'b5cb1e8b-d9f4-4a1b-bc18-6e50a3e5ef68';
UPDATE flashcards SET cloze_text = 'Sodium is far more concentrated {{c1::outside}} the neuron (~145 mM) than inside (~12 mM), so the Na⁺ gradient drives Na⁺ to flow {{c2::inward}} through leak channels.', cloze_count = 2 WHERE id = 'b6b07f5d-4c3b-4500-ad58-5f6fba941f17';
UPDATE flashcards SET cloze_text = 'Near +35 mV, Na⁺ channels inactivate and {{c1::voltage-gated K⁺ channels}} open; K⁺ exits the cell, driving the membrane back toward the resting potential — {{c2::repolarization}}.', cloze_count = 2 WHERE id = 'c7309d90-4847-4204-8227-e919a93e02d0';
UPDATE flashcards SET cloze_text = 'A Na⁺ channel in the {{c1::inactivated}} state cannot reopen until the membrane returns near the resting potential, where it is reset to the {{c2::closed}} state.', cloze_count = 2 WHERE id = 'cbdaefaf-fb83-45dc-8c6c-e9e0f6bdb935';
UPDATE flashcards SET cloze_text = 'A {{c1::synapse}} consists of the presynaptic terminal, the synaptic {{c2::cleft}}, and the postsynaptic membrane; most {{c1::synapses}} use a chemical messenger rather than direct electrical contact.', cloze_count = 2 WHERE id = 'ea0092c2-edeb-40cc-ade8-d44142929176';
UPDATE flashcards SET cloze_text = 'The K⁺ equilibrium potential is roughly {{c1::-90 mV}} and the Na⁺ equilibrium potential is roughly {{c2::+60 mV}}; the resting potential sits closer to K⁺''s because the membrane is more permeable to K⁺.', cloze_count = 2 WHERE id = 'f5ec0fcd-6f9a-4589-acb6-1514e71de32c';
UPDATE flashcards SET cloze_text = 'Conduction speed increases with axon {{c1::cross-sectional area}} (less resistance) and decreases with axon {{c2::length}}; {{c1::cross-sectional area}} is the more significant factor.', cloze_count = 2 WHERE id = 'fafaafe3-4361-496c-bbe9-f0a84d58c5a1';
-- ── The Respiratory System ──
UPDATE flashcards SET cloze_text = 'Two layers of serous membrane wrap each lung: the {{c1::visceral}} pleura hugs the lung surface (dipping into its fissures), while the {{c1::parietal}} pleura anchors to the thoracic wall, mediastinum, and diaphragm.', cloze_count = 1 WHERE id = '0fd383e2-8570-4811-9f0b-7774e24414cd';
UPDATE flashcards SET cloze_text = 'Under normal conditions the brain paces breathing off {{c1::CO₂}} (via the H⁺/pH it generates), so oxygen only becomes a significant ventilatory drive once arterial O₂ falls to roughly {{c2::60 mm Hg}} or lower — a threshold this low because the {{c3::peripheral}} chemoreceptors sense only dissolved O₂, and hemoglobin buffers the drop until levels are quite low.', cloze_count = 3 WHERE id = '10cc613a-8fab-42dd-b778-df87409e1c88';
UPDATE flashcards SET cloze_text = 'Deoxygenated blood leaves the {{c1::right ventricle}} through the {{c2::pulmonary arteries}} (the only post-natal {{c2::arteries}} carrying oxygen-poor blood), reaches the {{c3::pulmonary (lung) capillaries}} to load O₂ at the alveoli, then drains via the {{c4::pulmonary veins}} into the {{c5::left atrium}}, completing the pulmonary circuit.', cloze_count = 5 WHERE id = '11c29d37-68e5-4fb1-8f70-79cc4770ca37';
UPDATE flashcards SET cloze_text = 'In the equilibrium CO₂ + H₂O ⇌ H₂CO₃ ⇌ H⁺ + HCO₃⁻, {{c1::hypoventilation}} lets CO₂ accumulate in the blood, which drives the reaction {{c2::rightward}} toward more carbonic acid; the extra H⁺ liberated {{c3::lowers}} blood pH — the hallmark of respiratory {{c4::acidosis}}.', cloze_count = 4 WHERE id = '12620a6a-44d0-4fec-a2c1-4e0792fe94c6';
UPDATE flashcards SET cloze_text = 'In the bicarbonate buffer, {{c1::carbonic anhydrase}} accelerates the hydration of CO₂ to carbonic acid (H₂CO₃), which then dissociates into {{c2::H⁺ and HCO₃⁻}}; because every step is reversible, exhaling CO₂ pulls the whole chain leftward and raises blood pH.', cloze_count = 2 WHERE id = '13853dd8-5d73-4760-b346-5b42b91a4cc6';
UPDATE flashcards SET cloze_text = 'In the reaction CO₂ + H₂O ⇌ H₂CO₃ ⇌ HCO₃⁻ + H⁺, hyperventilation strips CO₂ from the blood, so the equilibrium slides {{c1::left (toward CO₂)}}; with fewer H⁺ ions remaining, blood pH {{c2::rises}}, tipping the patient toward respiratory {{c3::alkalosis}}.', cloze_count = 3 WHERE id = '174921d2-b737-471a-95a1-ccc7359829a9';
UPDATE flashcards SET cloze_text = 'At the alveolus during external respiration, O₂ travels {{c1::from air into the blood}} while CO₂ travels {{c2::from the blood into the air}} — the two gases cross the respiratory membrane in opposite directions because each follows its own {{c3::partial-pressure gradient}} (alveolar PO₂ ~104 vs. capillary ~40 mm Hg; capillary PCO₂ ~45 vs. alveolar ~40 mm Hg).', cloze_count = 3 WHERE id = '181a6cf9-7860-49c1-96da-8db2e1b36f8e';
UPDATE flashcards SET cloze_text = 'The {{c1::pulmonary}} arteries carry {{c2::deoxygenated}} blood along the {{c1::pulmonary}} circuit from the {{c3::right ventricle}} toward the lungs.', cloze_count = 3 WHERE id = '3be1b787-5250-40c0-911b-71b50de2cb07';
UPDATE flashcards SET cloze_text = 'When PaCO₂ climbs, dissolved CO₂ crosses the blood-brain barrier and lowers CSF pH; {{c1::central chemoreceptors}} in the medulla actually track this {{c2::H⁺ (falling pH)}} rather than CO₂ itself, and drive the respiratory center to {{c3::increase}} rate and depth — venting CO₂ until blood levels fall back to baseline (negative feedback).', cloze_count = 3 WHERE id = '44d0f367-219d-40c6-89b7-61e135c98202';
UPDATE flashcards SET cloze_text = 'When arterial H⁺ climbs and pH falls, {{c1::peripheral chemoreceptors}} in the aortic arch and carotid arteries fire, driving the medulla to {{c2::raise the respiratory rate}} so that more {{c3::CO₂}} is blown off — pulling H⁺ back down and restoring pH via negative feedback.', cloze_count = 3 WHERE id = '4cb8159b-c48a-4bdd-903a-0679205db29f';
UPDATE flashcards SET cloze_text = 'Sitting in the {{c1::carotid and aortic bodies}}, the peripheral chemoreceptors sample arterial {{c2::O₂, CO₂, and H⁺}} and relay that status to the brainstem respiratory centers. Because they read dissolved gas rather than hemoglobin-bound stores, a steep O₂ drop to roughly {{c3::60 mm Hg}} or lower is needed before they drive ventilation up.', cloze_count = 3 WHERE id = '4e46dd32-b042-48f1-b13b-adf7bdecf34c';
UPDATE flashcards SET cloze_text = 'Under normal conditions, the drive to breathe tracks blood {{c1::CO₂}}, not {{c2::O₂}} — because {{c1::CO₂}} crossing the blood-brain barrier raises {{c3::H⁺}} (lowering pH), and that acidity is what the {{c4::central}} chemoreceptors of the brainstem actually sense. Peripheral chemoreceptors only ramp up ventilation for {{c2::O₂}} once arterial partial pressure falls to roughly {{c5::60 mm Hg}} or lower.', cloze_count = 5 WHERE id = '9b21481d-02a0-4738-83fc-8c0495deae84';
UPDATE flashcards SET cloze_text = 'Chemoreceptors register rising blood CO₂ only {{c1::indirectly}}: the CO₂ reacts with water to yield {{c2::carbonic acid (H₂CO₃)}}, whose dissociation frees {{c3::H⁺}} ions, and it is that drop in pH — not the CO₂ molecule itself — that the receptors actually detect.', cloze_count = 3 WHERE id = 'a88d624b-a215-42a5-9bb1-b9d26eb77ed4';
UPDATE flashcards SET cloze_text = 'When acid-base balance is disturbed, the {{c1::lungs}} act within {{c2::minutes}} by exhaling {{c3::CO₂}} to raise pH, while the {{c4::kidneys}} deliver slower, long-term correction over {{c5::hours to days}} by secreting {{c6::H⁺}} and conserving {{c7::HCO₃⁻ (bicarbonate)}}.', cloze_count = 7 WHERE id = 'b30eff46-2eab-4bc4-bcd3-729c90016411';
UPDATE flashcards SET cloze_text = 'Air travels but never crosses into blood along the {{c1::conducting}} zone (trachea down through the terminal bronchioles); actual O₂/CO₂ diffusion is confined to the {{c2::respiratory}} zone, which begins at the {{c2::respiratory}} bronchioles and terminates in the {{c3::alveoli}}.', cloze_count = 3 WHERE id = 'bb48be8c-85a2-4122-a20a-d465a5fec8c7';
UPDATE flashcards SET cloze_text = 'Because flat {{c1::type I alveolar cells}} tile the alveolar wall as a layer just {{c2::one cell}} thick, an O₂ or CO₂ molecule crosses the respiratory membrane by traversing a barrier only ~{{c3::0.5 μm}} deep — the short {{c4::diffusion distance}} that lets simple diffusion keep pace with gas exchange.', cloze_count = 4 WHERE id = 'c521d64b-d34e-47de-be9f-a3a1395740ca';
UPDATE flashcards SET cloze_text = 'Where alveolar and capillary walls fuse, they build the {{c1::respiratory membrane}}, a barrier only about {{c2::0.5 μm}} thick — thin enough that O₂ and CO₂ slip across by {{c3::simple diffusion}} rather than active transport.', cloze_count = 3 WHERE id = 'ca7e6ddd-96c0-4e3f-af98-438ff2615e45';
UPDATE flashcards SET cloze_text = 'A {{c1::pulmonary capillary network}} sheathes every alveolus, so venous blood ends up a fraction of a micron from the alveolar air; the two thin walls fuse into the {{c2::respiratory membrane}} — only about {{c3::0.5 μm}} thick — across which O₂ and CO₂ diffuse.', cloze_count = 3 WHERE id = 'da201de3-7d4e-4b90-8e56-ffadb7c734cf';
UPDATE flashcards SET cloze_text = 'Scattered among the thin, flat cells of the alveolar wall, the cuboidal {{c1::type II alveolar cells}} release {{c2::pulmonary surfactant}}, a phospholipid-protein film that {{c3::lowers the surface tension}} of the watery alveolar lining and stops the alveoli from collapsing at the end of exhalation.', cloze_count = 3 WHERE id = 'f43f671b-0593-4b7f-833f-074c0f803ad5';

COMMIT;
